const appEl=document.getElementById('app');
const toastEl=document.getElementById('toast');
const primaryActionBtn=document.getElementById('primaryActionBtn');
const homeBtn=document.getElementById('homeBtn');
const brandHome=document.getElementById('brandHome');
const subbrand=document.getElementById('subbrand');
let records=[];
let currentInitialForm=null;
let generatedInitialPdf=null;

const STATUSES=['Awaiting 1st contact','Awaiting 2nd contact','Awaiting 3rd contact','Call referring doctor','Referring doctor contacted','Letter sent','Scheduled','Not booked'];
const esc=(v='')=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function fmtDate(v){if(!v)return '—';return esc(ClinicDates.toUSDate(v)||v)}
function fmtDateTime(v){if(!v)return '—';const d=new Date(v);if(Number.isNaN(d.getTime()))return esc(v);return d.toLocaleString('en-US',{month:'2-digit',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});}
function usDateValue(v){if(!v)return '';return ClinicDates.toUSDate(v)||String(v)}
function usDateTimeValue(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);return d.toLocaleString('en-US',{month:'2-digit',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}).replace(',','')}
function parseUsDate(v,label='Date'){const x=String(v||'').trim();if(!x)return '';const m=x.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!m)throw new Error(`${label} must use MM/DD/YYYY.`);const month=Number(m[1]),day=Number(m[2]),year=Number(m[3]);const d=new Date(year,month-1,day);if(d.getFullYear()!==year||d.getMonth()!==month-1||d.getDate()!==day)throw new Error(`${label} is not a valid date.`);return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function parseUsDateTime(v,label='Date/Time'){const x=String(v||'').trim();if(!x)return '';const m=x.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})\s*(AM|PM)$/i);if(!m)throw new Error(`${label} must use MM/DD/YYYY hh:mm AM/PM.`);const month=Number(m[1]),day=Number(m[2]),year=Number(m[3]),minute=Number(m[5]);let hour=Number(m[4]);if(month<1||month>12||day<1||day>31||hour<1||hour>12||minute<0||minute>59)throw new Error(`${label} is not valid.`);const ap=m[6].toUpperCase();if(ap==='AM'&&hour===12)hour=0;if(ap==='PM'&&hour!==12)hour+=12;const d=new Date(year,month-1,day,hour,minute);if(d.getFullYear()!==year||d.getMonth()!==month-1||d.getDate()!==day)throw new Error(`${label} is not valid.`);return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`}
function normalizeDates(data,fields){for(const [key,label] of fields)data[key]=parseUsDate(data[key],label||key);return data}
function dateTextInput(name,value='',required=false){return `<input type="text" class="us-date" inputmode="numeric" autocomplete="off" placeholder="MM/DD/YYYY" name="${name}" value="${esc(usDateValue(value))}"${required?' required':''}>`}
function time12Value(v){
  const x=String(v||'').trim();if(!x)return '';
  let m=x.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);if(m){const h=Number(m[1]),min=Number(m[2]);if(h>=1&&h<=12&&min>=0&&min<=59)return `${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')} ${m[3].toUpperCase()}`;return x}
  m=x.match(/^(\d{1,2}):(\d{2})$/);if(m){const h24=Number(m[1]),min=Number(m[2]);if(h24>=0&&h24<=23&&min>=0&&min<=59){const ap=h24>=12?'PM':'AM',h=h24%12||12;return `${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')} ${ap}`}}
  return x;
}
function parseTime12(v,label='Time'){const x=String(v||'').trim();if(!x)return '';const m=x.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);if(!m)throw new Error(`${label} must use hh:mm AM/PM.`);const h=Number(m[1]),min=Number(m[2]);if(h<1||h>12||min<0||min>59)throw new Error(`${label} is not valid.`);return `${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')} ${m[3].toUpperCase()}`}
function normalizeTimes(data,fields){for(const [key,label] of fields)data[key]=parseTime12(data[key],label||key);return data}
function normalizeExamType(v){const x=String(v||'').trim().toUpperCase();if(['FVDE','FDEV','VDE/FVDE','FVDE/VDE'].includes(x))return 'VDE';if(['FVIP','VIP/FVIP','FVIP/VIP'].includes(x))return 'VIP';return String(v||'').trim()}
function todayIso(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function todayUs(){return usDateValue(todayIso())}
function timeTextInput(name,value='',required=false){return `<input type="text" class="us-time" inputmode="text" autocomplete="off" placeholder="hh:mm AM/PM" name="${name}" value="${esc(time12Value(value))}"${required?' required':''}>`}
function nowUsDateTime(){return new Date().toLocaleString('en-US',{month:'2-digit',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}).replace(',','')}
document.addEventListener('input',e=>{if(!e.target.classList?.contains('us-date'))return;const raw=e.target.value.replace(/\D/g,'').slice(0,8);let out=raw;if(raw.length>2)out=raw.slice(0,2)+'/'+raw.slice(2);if(raw.length>4)out=raw.slice(0,2)+'/'+raw.slice(2,4)+'/'+raw.slice(4);e.target.value=out;});
function showToast(msg,type='success'){toastEl.textContent=msg;toastEl.className=`toast ${type}`;toastEl.hidden=false;clearTimeout(showToast.t);showToast.t=setTimeout(()=>toastEl.hidden=true,3500)}
function errorMessage(e){return e?.message||String(e||'Unknown error')}
function setHeader(label,actionText='',actionFn=null){subbrand.textContent=label;homeBtn.hidden=label==='Clinic Tools';primaryActionBtn.hidden=!actionText;primaryActionBtn.textContent=actionText;if(actionFn)primaryActionBtn.onclick=actionFn;}
function fatal(e,retry){appEl.innerHTML=`<section class="fatal-card"><h1>Unable to load</h1><p class="muted">The local data could not be loaded.</p><pre>${esc(errorMessage(e))}</pre><button class="btn btn-primary" id="retryBtn">Try Again</button></section>`;document.getElementById('retryBtn').onclick=retry||renderDashboard}

if(!window.clinicAPI) fatal(new Error('The local application bridge did not initialize. Please use the updated build.'));
homeBtn.onclick=renderDashboard;brandHome.onclick=renderDashboard;brandHome.onkeydown=e=>{if(e.key==='Enter')renderDashboard()};

function renderDashboard(){
  setHeader('Clinic Tools','+ New Initial Contact',renderInitialForm);
  appEl.innerHTML=`<section class="dashboard-hero"><div><h1>Clinic Tools</h1><p class="muted">Choose the workflow you want to use.</p></div></section>
  <div class="module-grid">
    <button class="module-card" id="referralModule"><div class="module-icon">↻</div><div><h2>Referral Follow-Up</h2><p>Track referral calls, comments, next steps, scheduling outcomes and referral PDFs.</p></div><span>Open →</span></button>
    <button class="module-card" id="initialModule"><div class="module-icon">▤</div><div><h2>Initial Contact and Patient Tracking</h2><p>Complete the official Initial Contact Form, generate the PDF and manage patient/deposit tracking in Excel.</p></div><span>Open →</span></button>
    <button class="module-card" id="cancellationModule"><div class="module-icon">×</div><div><h2>Exam Cancelations</h2><p>Use the cancellation scripts, document why an exam was cancelled or missed, and manage rescheduling follow-up in Excel.</p></div><span>Open →</span></button>
    <button class="module-card" id="setupModule"><div class="module-icon">✓</div><div><h2>New Patient Setup</h2><p>Track add-to-Crystal, Crystal scheduling, and the initial email after a new patient is scheduled.</p></div><span>Open →</span></button>
  </div>`;
  document.getElementById('referralModule').onclick=renderReferralHome;
  document.getElementById('initialModule').onclick=renderInitialLanding;
  document.getElementById('waitlistModule').onclick=()=>renderWaitlistLanding();
  document.getElementById('cancellationModule').onclick=renderCancellationLanding;
  document.getElementById('setupModule').onclick=renderSetupLanding;
}

// ---------------- Referral Follow-Up ----------------
async function renderReferralHome(){
  setHeader('Referral Follow-Up','+ New Initial Contact',renderInitialForm);
  appEl.innerHTML=`<section class="hero-row"><div><h1>Referrals</h1><p class="muted">Manage referrals that still need action and keep completed outcomes out of the active work queue.</p></div></section><div class="card"><p class="muted">Loading referrals…</p></div>`;
  try{records=await window.clinicAPI.listReferrals();}catch(e){fatal(e,renderReferralHome);return;}
  appEl.innerHTML=`<section class="hero-row"><div><h1>Referrals</h1><p class="muted">Manage referrals that still need action and keep completed outcomes out of the active work queue.</p></div><div class="inline-actions"><button class="btn" id="exportRefDrReport">Export Referring Dr Report</button><button class="btn btn-primary" id="newReferralInline">+ New Referral</button></div></section>
  <div class="toolbar"><input id="searchInput" class="search" type="search" placeholder="Search patient, concern, evaluation..."><select id="statusFilter"><option value="">All statuses</option>${STATUSES.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select><button id="searchBtn" class="btn">Search</button><button id="clearBtn" class="btn btn-ghost" style="display:none">Clear</button></div><div id="homeLists"></div><div id="dataLocation" class="data-location"></div>`;
  document.getElementById('newReferralInline').onclick=()=>renderReferralForm();document.getElementById('exportRefDrReport').onclick=async()=>{try{const p=await window.clinicAPI.exportReferringDoctorReport();if(p)showToast('Report saved: '+p)}catch(e){showToast(errorMessage(e),'error')}};document.getElementById('searchBtn').onclick=renderReferralLists;document.getElementById('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')renderReferralLists()});document.getElementById('statusFilter').onchange=renderReferralLists;document.getElementById('clearBtn').onclick=()=>{document.getElementById('searchInput').value='';document.getElementById('statusFilter').value='';renderReferralLists()};renderReferralLists();
  try{document.getElementById('dataLocation').textContent=`Local data: ${await window.clinicAPI.getDataLocation()}`}catch{}
}
function renderReferralLists(){const q=(document.getElementById('searchInput')?.value||'').trim().toLowerCase(),sf=document.getElementById('statusFilter')?.value||'';document.getElementById('clearBtn').style.display=(q||sf)?'inline-flex':'none';const filtered=records.filter(r=>{const h=[r['Patient Name'],r['DOB'],r['Parent Name'],r['Phone'],r['Email'],r['Referring Doctor'],r['Referring Doctor Phone'],r['Office Name'],r['Recommended Evaluation'],r['Patient/Parent Concerns or Symptoms']].join(' ').toLowerCase();return(!q||h.includes(q))&&(!sf||r._status===sf)});const active=filtered.filter(r=>!['Scheduled','Not booked'].includes(r._status)),closed=filtered.filter(r=>['Scheduled','Not booked'].includes(r._status));document.getElementById('homeLists').innerHTML=referralSection('Needs Follow-Up','Patients who still require contact or another next step.',active,false)+referralSection('Scheduled / Not Booking','Patients who scheduled or chose not to schedule.',closed,true);document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>renderReferralDetail(Number(el.dataset.open)))}
function referralLastContact(r){for(const p of ['3rd','2nd','1st']){if(r[`${p} Contact - Date/Time`])return {date:r[`${p} Contact - Date/Time`],comment:r[`${p} Contact - Comment`]||''};}return {date:'',comment:''};}
function referralSection(title,desc,list,closed){return `<section class="home-section ${closed?'closed-section':''}"><div class="section-title-row"><div><h2>${title}</h2><p class="muted small">${desc}</p></div><span class="count-badge ${closed?'neutral':''}">${list.length}</span></div><div class="table-card"><table><thead><tr><th>Patient</th><th>Referral Date</th><th>Evaluation</th><th>Last Contact</th><th>Last Comment</th><th>${closed?'Outcome':'Status'}</th><th></th></tr></thead><tbody>${list.length?list.map(r=>{const last=referralLastContact(r);return `<tr><td><strong>${esc(r['Patient Name'])}</strong></td><td>${fmtDate(r['Date'])}</td><td>${esc(r['Recommended Evaluation']||'—')}</td><td>${fmtDateTime(last.date)}</td><td class="comment-cell">${esc(last.comment||'—')}</td><td><span class="status ${r._status==='Scheduled'?'status-scheduled':r._status==='Not booked'?'status-closed':'status-active'}">${esc(r._status)}</span></td><td class="right"><button class="btn btn-open-referral" data-open="${r._row}">Open →</button></td></tr>`}).join(''):`<tr><td colspan="7" class="empty">${closed?'No scheduled or not-booking referrals found.':'No referrals currently need follow-up.'}</td></tr>`}</tbody></table></div></section>`}
function formValue(r,k){return esc(r?.[k]||'')}

function referralPersonValues(r={}){
  const patient=String(r['Patient Name']||'').trim()||'[patient name]';
  const doctorRaw=String(r['Referring Doctor']||'').trim();
  const doctor=doctorRaw?(doctorRaw.toLowerCase().startsWith('dr.')||doctorRaw.toLowerCase().startsWith('dr ')?doctorRaw:`Dr. ${doctorRaw}`):'Dr. [Dr name]';
  const office=String(r['Office Name']||'').trim()||'[office name]';
  return {patient,doctor,office};
}
function referralContactScript(attempt,r={}){
  const {patient,doctor,office}=referralPersonValues(r);
  if(Number(attempt)===1){
    const text=`Good afternoon! This is Julia with the Visual Health and Learning Center, I hope all is well. We received a referral from ${doctor} at ${office} to get ${patient} scheduled for additional testing for vision dysfunction that cannot be corrected with eyeglasses alone. I'm going to give you a call in a moment, but if this time doesn't work for you, please text me back and let me know what time & day works best.`;
    const call=`Good morning/afternoon, this is Julia with Visual Health & Learning Center calling regarding a referral that we received from ${doctor}/${office} regarding ${patient}. It looks like here we need to schedule an additional vision evaluation due to some concerns your doctor had. Do you have time to take care of that right now?`;
    const vm=`Good morning/afternoon, this is Julia with Visual Health & Learning Center calling regarding a referral that we received from ${doctor}/${office} regarding ${patient}. It looks like here we need to schedule an additional vision evaluation due to some concerns your doctor had regarding ${patient}'s vision. Please give us a call back at (407) 277-5729 at your earliest convenience to get that scheduled. Thank you and we look forward to hearing from you.`;
    return `<div class="contact-script"><h4>1st Contact Script</h4><details><summary>Text before calling</summary><div class="script-copy-row"><button type="button" class="copy-btn copy-script-btn" data-copy-text="${encodeURIComponent(text)}">Copy message</button></div><p>${esc(text)}</p></details><details open><summary>Phone call</summary><p>${esc(call)}</p></details><details><summary>Voicemail</summary><p>${esc(vm)}</p></details></div>`;
  }
  if(Number(attempt)===2){
    const call=`Good morning/afternoon, this is Julia with Visual Health and Learning Center following up regarding a referral we received from ${doctor}/${office} to get ${patient} scheduled with us. I just wanted to touch base and see if that was something you were still interested in?`;
    const vm=`Good morning/afternoon, this is Julia with Visual Health and Learning Center following up regarding a referral we received from ${doctor}/${office} to get ${patient} scheduled with us. If this is something that you're still interested in, please give us a call back at (407) 277-5729 at your earliest convenience to get that scheduled. Thank you and we look forward to hearing from you!`;
    return `<div class="contact-script"><h4>2nd Contact — Follow-Up Script</h4><details open><summary>Phone call</summary><p>${esc(call)}</p></details><details><summary>Voicemail</summary><p>${esc(vm)}</p></details></div>`;
  }
  const call=`Good morning/afternoon, this is Julia with Visual Health and Learning Center following up regarding a referral we received from ${doctor}/${office} to get ${patient} scheduled with us. I just wanted to touch base and see if that was something you were still interested in?`;
  const vm=`Good morning/afternoon, this is Julia with Visual Health and Learning Center, just reaching out for a final time regarding the referral we received from ${doctor}/${office} to get ${patient} scheduled with us. If an additional vision evaluation is something that you're still interested in, or if you do decide sometime in the future that you are in need of our services, please feel free to give us a call at (407) 277-5729 at your earliest convenience and I'd be happy to help getting you on the books. Thank you and we hope to hear from you!`;
  return `<div class="contact-script"><h4>3rd Contact — Final Follow-Up Script</h4><details open><summary>Phone call</summary><p>${esc(call)}</p></details><details><summary>Voicemail</summary><p>${esc(vm)}</p></details></div>`;
}
function wireScriptCopyButtons(){document.querySelectorAll('.copy-script-btn').forEach(btn=>btn.onclick=async()=>{try{await window.clinicAPI.copyText(decodeURIComponent(btn.dataset.copyText||''));showToast('Message copied.')}catch(e){showToast(errorMessage(e),'error')}})}

async function renderReferralForm(rowNumber=null){
  setHeader('Referral Follow-Up');let r={};
  if(rowNumber){try{r=await window.clinicAPI.getReferral(rowNumber)}catch(e){fatal(e,renderReferralHome);return}if(!r){showToast('Referral not found.','error');return}}
  const grades=['Preschool','PreKindergarten','Kindergarten','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th','11th','12th','College'];
  appEl.innerHTML=`<div class="form-shell"><div class="section-heading"><div><h1>${rowNumber?'Edit Referral':'New Referral'}</h1><p class="muted">Referral details, demographics, follow-up information and documents are stored together.</p></div>${!rowNumber?`<button type="button" class="btn" id="importReferralJsonBtn">Import Referral JSON</button>`:''}</div>${!rowNumber?`<div class="json-import-card" id="referralJsonPanel" hidden><h3>Import Referral JSON</h3><p class="muted small">Paste the JSON generated from the referral image, review the preview, then fill the form.</p><textarea id="referralJsonInput" rows="9" placeholder='{"patient_name":"...","dob":"MM/DD/YYYY",...}'></textarea><div class="inline-actions"><button type="button" class="btn" id="previewReferralJson">Preview</button><button type="button" class="btn btn-primary" id="applyReferralJson" disabled>Use These Values</button></div><div id="referralJsonPreview" class="json-preview"></div></div>`:''}<form id="refForm" class="form-card">
  <h2>Patient & Referral</h2><div class="grid three"><label>Date${dateTextInput('Date',r?.['Date']||todayIso())}</label><label>Patient Name *<input type="text" required name="Patient Name" value="${formValue(r,'Patient Name')}"></label><label>Age<input type="number" min="0" max="130" name="Age" value="${formValue(r,'Age')}"></label><label>DOB${dateTextInput('DOB',r?.['DOB'])}</label><label>Parent Name<input name="Parent Name" value="${formValue(r,'Parent Name')}"></label><label>Phone<input name="Phone" value="${formValue(r,'Phone')}"></label><label class="span-2">Email<input type="email" name="Email" value="${formValue(r,'Email')}"></label><label>Grade<select name="Grade"><option value=""></option>${grades.map(x=>`<option ${r?.['Grade']===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Referring Doctor<input name="Referring Doctor" value="${formValue(r,'Referring Doctor')}" placeholder="Doctor name"></label><label>Referring Doctor Phone<input name="Referring Doctor Phone" value="${formValue(r,'Referring Doctor Phone')}" placeholder="Doctor office phone"></label><label>Office Name<input name="Office Name" value="${formValue(r,'Office Name')}" placeholder="Referring office"></label><label class="span-2">Recommended Evaluation<input type="text" name="Recommended Evaluation" value="${formValue(r,'Recommended Evaluation')}"></label><label class="span-3">Patient/Parent Concerns or Symptoms<textarea name="Patient/Parent Concerns or Symptoms" rows="4">${formValue(r,'Patient/Parent Concerns or Symptoms')}</textarea></label><label class="span-3 file-field">Referral Files (up to 3 PDFs)<div class="file-picker"><input id="pdfName" readonly value="${r?._pdf_files?.length?r._pdf_files.map(x=>x.name).join(', '):''}" placeholder="No PDFs selected"><button type="button" id="choosePdf" class="btn">Choose PDFs</button></div><span class="field-help">You can attach 1 to 3 PDF files to the same patient.</span></label></div>
  <h2>Contact Attempts</h2>${['1st','2nd','3rd'].map(p=>`<div class="contact-edit-row"><label>${p} Contact - Date/Time<input type="text" autocomplete="off" placeholder="MM/DD/YYYY hh:mm AM/PM" name="${p} Contact - Date/Time" value="${esc(usDateTimeValue(r?.[`${p} Contact - Date/Time`]))}"></label><label>Comment<textarea name="${p} Contact - Comment" rows="3">${formValue(r,`${p} Contact - Comment`)}</textarea></label></div>`).join('')}
  <h2>Next Steps</h2><div class="grid three"><label>Call Referring Dr.${dateTextInput('Call Referring Dr.',r?.['Call Referring Dr.'])}</label><label>Letter to Patient${dateTextInput('Letter to Patient',r?.['Letter to Patient'])}</label><label>Thank You Letter${dateTextInput('Thank You Letter',r?.['Thank You Letter'])}</label><label class="span-3">Reason for Not Booking<textarea name="Reason for Not Booking" rows="4">${formValue(r,'Reason for Not Booking')}</textarea></label></div><div class="form-actions"><button type="button" id="cancelBtn" class="btn btn-ghost">Cancel</button><button type="submit" class="btn btn-primary">${rowNumber?'Save Changes':'Save Referral'}</button></div></form></div>`;
  if(!rowNumber){
    const importBtn=document.getElementById('importReferralJsonBtn'),panel=document.getElementById('referralJsonPanel'),preview=document.getElementById('referralJsonPreview'),apply=document.getElementById('applyReferralJson');let mappedJson=null;
    const mapJson=(obj)=>{const pick=(...keys)=>{for(const k of keys)if(obj[k]!==undefined&&obj[k]!==null)return obj[k];return ''};return {'Date':pick('referral_date','date','Date'),'Patient Name':pick('patient_name','patientName','Patient Name'),'Age':pick('age','Age'),'DOB':pick('dob','DOB'),'Parent Name':pick('parent_name','parentName','Parent Name'),'Phone':pick('phone','Phone'),'Email':pick('email','Email'),'Grade':pick('grade','Grade'),'Referring Doctor':pick('referring_doctor','doctor_name','referringDoctor','Referring Doctor'),'Office Name':pick('office_name','officeName','Office Name'),'Referring Doctor Phone':pick('referring_doctor_phone','doctor_phone','referringDoctorPhone','Referring Doctor Phone'),'Recommended Evaluation':pick('recommended_evaluation','recommendedEvaluation','Recommended Evaluation'),'Patient/Parent Concerns or Symptoms':pick('concerns_symptoms','parent_concerns','symptoms','Patient/Parent Concerns or Symptoms')};};
    importBtn.onclick=()=>{panel.hidden=!panel.hidden};
    document.getElementById('previewReferralJson').onclick=()=>{try{const obj=JSON.parse(document.getElementById('referralJsonInput').value);mappedJson=mapJson(obj);const rows=Object.entries(mappedJson).filter(([,v])=>String(v??'').trim()).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('');preview.innerHTML=rows||'<p class="muted">No recognized fields were found.</p>';apply.disabled=!rows}catch(e){mappedJson=null;apply.disabled=true;preview.innerHTML=`<div class="flash error">Invalid JSON: ${esc(errorMessage(e))}</div>`}};
    apply.onclick=()=>{if(!mappedJson)return;const form=document.getElementById('refForm');for(const [k,v0] of Object.entries(mappedJson)){if(v0===undefined||v0===null||String(v0).trim()==='')continue;let v=String(v0);if(k==='Date'||k==='DOB'){const iso=v.match(/^\d{4}-\d{2}-\d{2}$/)?usDateValue(v):v;v=iso}const el=form.elements.namedItem(k);if(el)el.value=v}panel.hidden=true;showToast('Referral fields filled from JSON. Please review before saving.')};
  }
  let pdfPaths=[];const existingPdfCount=r?._pdf_files?.length||0;
  document.getElementById('choosePdf').onclick=async()=>{try{const picked=await window.clinicAPI.chooseReferralPdfs();if(!picked?.length)return;if(existingPdfCount+picked.length>3){showToast(`This patient can have at most 3 referral PDFs. ${3-existingPdfCount} slot(s) remain.`,'error');return}pdfPaths=picked;const existingNames=r?._pdf_files?.map(x=>x.name)||[];document.getElementById('pdfName').value=[...existingNames,...picked.map(p=>p.split(/[\\/]/).pop())].join(', ')}catch(e){showToast(errorMessage(e),'error')}};
  document.getElementById('cancelBtn').onclick=()=>rowNumber?renderReferralDetail(rowNumber):renderReferralHome();
  document.getElementById('refForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());try{normalizeDates(data,[['Date','Date'],['DOB','DOB'],['Call Referring Dr.','Call Referring Dr.'],['Letter to Patient','Letter to Patient'],['Thank You Letter','Thank You Letter']]);for(const p of ['1st','2nd','3rd'])data[`${p} Contact - Date/Time`]=parseUsDateTime(data[`${p} Contact - Date/Time`],`${p} Contact - Date/Time`)}catch(err){showToast(errorMessage(err),'error');return}data._pdfSourcePaths=pdfPaths;try{const res=rowNumber?await window.clinicAPI.updateReferral(rowNumber,data):await window.clinicAPI.createReferral(data);if(res?.moveWarnings?.length)showToast(`${rowNumber?'Referral updated':'Referral saved'}, but ${res.moveWarnings.join(' ')}`,'error');else showToast(rowNumber?'Referral updated. PDFs moved to clinic data.':'Referral saved. PDFs moved to clinic data.');renderReferralDetail(rowNumber||res.rowNumber)}catch(err){showToast(errorMessage(err),'error')}};
}

async function renderReferralDetail(rowNumber){
  setHeader('Referral Follow-Up');let r;try{r=await window.clinicAPI.getReferral(rowNumber)}catch(e){fatal(e,renderReferralHome);return}if(!r)return;
  const closed=['Scheduled','Not booked'].includes(r._status);
  const source=[r['Referring Doctor'],r['Office Name']].filter(Boolean).join(' / ');
  const contactDone=['1st','2nd','3rd'].filter(p=>r[`${p} Contact - Date/Time`]).length;
  const callDrDefault=r['Call Referring Dr.']||((contactDone>=3&&!closed)?todayIso():'');
  const letterDefault=r['Letter to Patient']||((r['Call Referring Dr.']&&!r['Letter to Patient'])?todayIso():'');
  const thankDefault=r['Thank You Letter']||((r['Letter to Patient']&&!r['Thank You Letter'])?todayIso():'');
  const doctorScriptName=String(r['Referring Doctor']||'').replace(/^Dr\.?\s*/i,'').trim()||'[Name]';
  const contactDrScript=`Hi, this is Julia calling from Visual Health & Learning Center. I'm calling regarding a patient referred to us by Dr. ${doctorScriptName}. I just wanted to let your office know that we reached out to the family, but they never scheduled an evaluation with us. We wanted to make sure your office was aware, so you may want to make a note in the patient's chart that they did not follow through with the referral. Thank you!`;
  appEl.innerHTML=`<div class="detail-head"><div><a class="back" id="backHome">← Back to referrals</a><h1>${esc(r['Patient Name'])}</h1><span class="status ${r._status==='Scheduled'?'status-scheduled':r._status==='Not booked'?'status-closed':'status-active'}">${esc(r._status)}</span></div><div class="detail-actions"><button id="startInitialBtn" class="btn btn-primary">Start Initial Contact</button>${r._status!=='Scheduled'?`<button id="scheduleBtn" class="btn btn-success">✓ Mark as Scheduled</button>`:`<button id="followBtn" class="btn">Return to Follow-Up</button>`}<button id="editBtn" class="btn">Edit referral</button><button id="deleteReferralBtn" class="btn btn-danger">Delete</button></div></div>
  <div class="detail-grid"><section class="card span-all"><div class="card-title-row"><h2>Patient & Referral Information</h2>${r._pdf_files?.length?`<div class="referral-file-actions">${r._pdf_files.map((f,i)=>f.exists?`<button class="btn referral-pdf-btn" data-pdf-index="${i}">View PDF ${i+1}</button>`:`<span class="missing-file">PDF ${i+1} missing</span>`).join('')}</div>`:''}</div><dl class="facts facts-wide"><div><dt>Patient Name</dt><dd>${esc(r['Patient Name']||'—')}</dd></div><div><dt>Referral Date</dt><dd>${fmtDate(r['Date'])}</dd></div><div><dt>Date of Birth</dt><dd>${fmtDate(r['DOB'])}</dd></div><div><dt>Age</dt><dd>${esc(r['Age']||'—')}</dd></div><div><dt>Parent Name</dt><dd>${esc(r['Parent Name']||'—')}</dd></div><div><dt>Phone</dt><dd>${esc(r['Phone']||'—')}</dd></div><div><dt>Email</dt><dd>${esc(r['Email']||'—')}</dd></div><div><dt>Grade</dt><dd>${esc(r['Grade']||'—')}</dd></div><div><dt>Referring Doctor</dt><dd>${esc(r['Referring Doctor']||'—')}</dd></div><div><dt>Referring Doctor Phone</dt><dd>${esc(r['Referring Doctor Phone']||'—')}</dd></div><div><dt>Office Name</dt><dd>${esc(r['Office Name']||'—')}</dd></div><div><dt>Recommended Evaluation</dt><dd>${esc(r['Recommended Evaluation']||'—')}</dd></div><div class="full"><dt>Patient/Parent Concerns or Symptoms</dt><dd class="pre">${esc(r['Patient/Parent Concerns or Symptoms']||'—')}</dd></div></dl></section>
  <section class="card"><h2>Contact History</h2><div class="timeline">${['1st','2nd','3rd'].map((p,i)=>`<div class="timeline-item ${r[`${p} Contact - Date/Time`]?'done':''}"><div class="timeline-dot">${i+1}</div><div><strong>${p} Contact</strong><div class="muted small">${fmtDateTime(r[`${p} Contact - Date/Time`])}</div><div class="comment">${esc(r[`${p} Contact - Comment`]||'No comment')}</div></div></div>`).join('')}</div>${r._next_attempt&&!closed?`<form id="contactForm" class="quick-form"><input type="hidden" name="attempt" value="${r._next_attempt}"><h3>Add contact attempt ${r._next_attempt}</h3>${referralContactScript(r._next_attempt,r)}<label>Date/Time<div class="datetime-with-action"><input id="contactDateTime" type="text" autocomplete="off" placeholder="MM/DD/YYYY hh:mm AM/PM" name="contact_datetime" value="${esc(nowUsDateTime())}" required><button type="button" class="btn btn-ghost" id="useNowContact">Now</button></div></label><label>Comment<textarea name="comment" rows="3"></textarea></label><button class="btn btn-primary" type="submit">Save contact</button></form>`:''}</section>
  <section class="card"><h2>Next Steps</h2><form id="nextStepsForm"><div class="grid one"><label>Call Referring Dr.${dateTextInput('Call Referring Dr.',callDrDefault)}</label><div class="next-step-script"><strong>Contact Referring Dr. Script</strong><p>${esc(contactDrScript)}</p><button type="button" class="btn btn-ghost copy-contact-dr-script" data-copy-text="${encodeURIComponent(contactDrScript)}">Copy Script</button></div><label>Letter to Patient${dateTextInput('Letter to Patient',letterDefault)}</label><label>Thank You Letter${dateTextInput('Thank You Letter',thankDefault)}</label><label>Reason for Not Booking<textarea name="Reason for Not Booking" rows="4">${formValue(r,'Reason for Not Booking')}</textarea></label></div><div class="form-actions compact"><button class="btn btn-primary">Save Next Steps</button></div></form></section></div>`;
  document.getElementById('backHome').onclick=renderReferralHome;
  document.getElementById('editBtn').onclick=()=>renderReferralForm(rowNumber);
  document.getElementById('startInitialBtn').onclick=()=>renderInitialForm({patientName:r['Patient Name']||'',age:r['Age']||'',dob:r['DOB']||'',parentName:r['Parent Name']||'',phone:r['Phone']||'',email:r['Email']||'',grade:r['Grade']||'',referralSource:source||r['Referring Doctor']||r['Office Name']||'',nonDoctorNotes:r['Patient/Parent Concerns or Symptoms']||''});
  document.getElementById('deleteReferralBtn').onclick=async()=>{if(!confirm(`Delete ${r['Patient Name']} from Referral Follow-Up? A workbook backup will be created first.`))return;try{await window.clinicAPI.deleteReferral(rowNumber);showToast('Referral deleted.');renderReferralHome()}catch(e){showToast(errorMessage(e),'error')}};
  document.querySelectorAll('.referral-pdf-btn').forEach(btn=>btn.onclick=()=>window.clinicAPI.openReferralPdf(rowNumber,Number(btn.dataset.pdfIndex)).catch(e=>showToast(errorMessage(e),'error')));
  wireScriptCopyButtons();
  document.querySelectorAll('.copy-contact-dr-script').forEach(btn=>btn.onclick=async()=>{try{await window.clinicAPI.copyText(decodeURIComponent(btn.dataset.copyText||''));showToast('Script copied.')}catch(e){showToast(errorMessage(e),'error')}});
  const nowBtn=document.getElementById('useNowContact');if(nowBtn)nowBtn.onclick=()=>{document.getElementById('contactDateTime').value=nowUsDateTime()};
  if(document.getElementById('scheduleBtn'))document.getElementById('scheduleBtn').onclick=async()=>{if(confirm('Mark this patient as scheduled?')){await window.clinicAPI.setBookingStatus(rowNumber,'Scheduled');renderReferralDetail(rowNumber)}};
  if(document.getElementById('followBtn'))document.getElementById('followBtn').onclick=async()=>{await window.clinicAPI.setBookingStatus(rowNumber,'');renderReferralDetail(rowNumber)};
  const cf=document.getElementById('contactForm');if(cf)cf.onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(cf).entries());try{payload.contact_datetime=parseUsDateTime(payload.contact_datetime,'Date/Time')}catch(err){showToast(errorMessage(err),'error');return}try{await window.clinicAPI.addContact(rowNumber,payload);showToast('Contact saved.');renderReferralDetail(rowNumber)}catch(err){showToast(errorMessage(err),'error')}};
  document.getElementById('nextStepsForm').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());try{normalizeDates(payload,[['Call Referring Dr.'],['Letter to Patient'],['Thank You Letter']])}catch(err){showToast(errorMessage(err),'error');return}try{await window.clinicAPI.updateNextSteps(rowNumber,payload);showToast('Next Steps saved.');renderReferralDetail(rowNumber)}catch(err){showToast(errorMessage(err),'error')}};
}

// ---------------- Initial Contact ----------------
async function renderInitialLanding(){
  setHeader('Initial Contact and Patient Tracking','+ New Initial Contact',renderInitialForm);
  let info,tracking;
  try{[info,tracking]=await Promise.all([window.clinicAPI.getInitialInfo(),window.clinicAPI.listInitialTracking()])}catch(e){fatal(e,renderInitialLanding);return}
  const mapping=info.analysis?.mapping||{};
  const all=tracking.records||[];
  const needsPayment=all.filter(r=>['Pending','Needs review'].includes(r._depositState));
  const completePayment=all.filter(r=>['Paid','No deposit required','No payment required'].includes(r._depositState));
  appEl.innerHTML=`<section class="hero-row"><div><h1>Initial Contact and Patient Tracking</h1><p class="muted">Create Initial Contact forms and manage the monthly patient/deposit tracking workbook from one place.</p></div><button class="btn" id="quickAddInitial">+ Add Patient to Tracking Only</button></section>
  <section class="card workbook-strip"><div class="card-title-row"><div><h2>Current Tracking Spreadsheet</h2><p class="muted small">Choose a new Excel file whenever the clinic starts a new monthly tracking workbook.</p></div><span class="status ${info.usingSimulation?'status-warning':'status-scheduled'}">${info.usingSimulation?'SIMULATION':'CONNECTED'}</span></div><div class="workbook-meta"><div><span>Workbook</span><strong class="path-text">${esc(info.workbookPath)}</strong></div><div><span>Worksheet</span><strong>${esc(info.analysis.worksheet)}</strong></div><div><span>Header row</span><strong>${info.analysis.headerRow}</strong></div><div><span>Fields</span><strong>${Object.keys(mapping).length}/9</strong></div></div><div class="inline-actions"><button class="btn btn-primary" id="connectWorkbook">Choose / Change Excel</button>${!info.usingSimulation?`<button class="btn" id="useSimulation">Use Simulation</button>`:''}</div></section>
  <div class="toolbar"><input id="initialSearch" class="search" type="search" placeholder="Search patient, referral source, exam type..."><button id="initialSearchBtn" class="btn">Search</button><button id="initialClearBtn" class="btn btn-ghost" style="display:none">Clear</button></div>
  <div id="initialLists"></div>`;
  const draw=()=>{const q=(document.getElementById('initialSearch')?.value||'').trim().toLowerCase();document.getElementById('initialClearBtn').style.display=q?'inline-flex':'none';const matches=r=>!q||[r.patientName,r.referralSource,r.examType,r.depositTaken,r.depositNeeded].join(' ').toLowerCase().includes(q);const pending=needsPayment.filter(matches),done=completePayment.filter(matches);document.getElementById('initialLists').innerHTML=initialTrackingSection('Needs Deposit Follow-Up','Only patients whose payment still needs to be tracked.',pending,false)+initialTrackingSection('Paid / No Payment Required','Patients who paid or do not require payment follow-up.',done,true);document.querySelectorAll('[data-open-initial]').forEach(el=>el.onclick=()=>renderInitialTrackingDetail(Number(el.dataset.openInitial)))};
  document.getElementById('initialSearchBtn').onclick=draw;document.getElementById('initialSearch').addEventListener('keydown',e=>{if(e.key==='Enter')draw()});document.getElementById('initialClearBtn').onclick=()=>{document.getElementById('initialSearch').value='';draw()};draw();
  document.getElementById('quickAddInitial').onclick=renderInitialQuickAdd;
  document.getElementById('connectWorkbook').onclick=async()=>{try{const chosen=await window.clinicAPI.chooseInitialWorkbook();if(!chosen)return;if(chosen.analysis.score<9){showToast(`Workbook detected, but only ${chosen.analysis.score}/9 required fields matched.`, 'error');return}await window.clinicAPI.connectInitialWorkbook(chosen.filePath);showToast('Excel workbook connected.');renderInitialLanding()}catch(e){showToast(errorMessage(e),'error')}};
  if(document.getElementById('useSimulation'))document.getElementById('useSimulation').onclick=async()=>{await window.clinicAPI.useSimulationWorkbook();renderInitialLanding()};
}

function initialTrackingSection(title,desc,list,paid){return `<section class="home-section ${paid?'':'closed-section'}"><div class="section-title-row"><div><h2>${title}</h2><p class="muted small">${desc}</p></div><span class="count-badge ${paid?'':'neutral'}">${list.length}</span></div><div class="table-card"><table><thead><tr><th>Patient</th><th>Initial Contact</th><th>Exam</th><th>Exam Date</th><th>Deposit</th><th></th></tr></thead><tbody>${list.length?list.map(r=>`<tr><td><strong>${esc(r.patientName)}</strong><div class="muted small">${esc(r.referralSource||'')}</div></td><td>${fmtDate(r.initialContactDate)}</td><td>${esc(r.examType||'—')}</td><td>${fmtDate(r.examScheduled)}</td><td><span class="status ${depositStatusClass(r._depositState)}">${esc(r._depositState)}</span>${r.depositTaken&&r.depositTaken!=='YES'?`<div class="muted small deposit-note">${esc(r.depositTaken)}</div>`:''}</td><td class="right"><a class="link" data-open-initial="${r._row}">Open →</a></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No patients in this section.</td></tr>`}</tbody></table></div></section>`}
function depositStatusClass(s){return s==='Paid'?'status-scheduled':s==='Pending'?'status-warning':s==='No deposit required'||s==='No payment required'?'status-closed':'status-active'}

async function renderInitialTrackingDetail(rowNumber){
  setHeader('Initial Contact and Patient Tracking');let r;try{r=await window.clinicAPI.getInitialTracking(rowNumber)}catch(e){fatal(e,renderInitialLanding);return}if(!r){showToast('Patient was not found in the selected Excel file.','error');renderInitialLanding();return}
  appEl.innerHTML=`<div class="detail-head"><div><a class="back" id="backInitialHome">← Back to Initial Contact and Patient Tracking</a><h1>${esc(r.patientName)}</h1><span class="status ${depositStatusClass(r._depositState)}">${esc(r._depositState)}</span></div><div class="detail-actions"><button id="deleteInitialTracking" class="btn btn-danger">Delete Patient</button><button id="editInitialTracking" class="btn btn-primary">Edit Tracking</button></div></div><div class="detail-grid"><section class="card span-all"><h2>Patient & Appointment</h2><dl class="facts facts-wide"><div><dt>Patient Name</dt><dd>${esc(r.patientName||'—')}</dd></div><div><dt>Age</dt><dd>${esc(r.age||'—')}</dd></div><div><dt>Initial Contact</dt><dd>${fmtDate(r.initialContactDate)}</dd></div><div><dt>Referral Source</dt><dd>${esc(r.referralSource||'—')}</dd></div><div><dt>Exam Type</dt><dd>${esc(r.examType||'—')}</dd></div><div><dt>Exam Scheduled</dt><dd>${fmtDate(r.examScheduled)}</dd></div><div><dt>Parent Meeting</dt><dd>${fmtDate(r.parentMeeting)}</dd></div></dl></section><section class="card span-all"><h2>Deposit</h2><dl class="facts facts-wide"><div><dt>Deposit Needed?</dt><dd>${esc(r.depositNeeded||'—')}</dd></div><div><dt>Deposit Taken?</dt><dd>${esc(r.depositTaken||'Pending')}</dd></div><div><dt>Current Status</dt><dd><span class="status ${depositStatusClass(r._depositState)}">${esc(r._depositState)}</span></dd></div></dl></section></div>`;
  document.getElementById('backInitialHome').onclick=renderInitialLanding;
  document.getElementById('editInitialTracking').onclick=()=>renderInitialTrackingEdit(rowNumber,r);
  document.getElementById('deleteInitialTracking').onclick=async()=>{
    const ok=confirm(`Delete ${r.patientName} from the currently selected Excel workbook?\n\nA backup of the workbook will be created first. Any generated PDF will be kept.`);
    if(!ok)return;
    try{
      await window.clinicAPI.deleteInitialTracking(rowNumber);
      showToast(`${r.patientName} was deleted from the tracking Excel.`);
      renderInitialLanding();
    }catch(err){showToast(errorMessage(err),'error')}
  };
}

function renderInitialTrackingEdit(rowNumber,r){
  setHeader('Initial Contact and Patient Tracking');appEl.innerHTML=`<div class="form-shell"><div class="section-heading"><div><a class="back" id="cancelInitialEdit">← Back to patient</a><h1>Edit Deposit Tracking</h1><p class="muted">Changes are written directly to the currently selected monthly Excel workbook.</p></div></div><form id="initialTrackingEdit" class="form-card"><h2>Patient & Appointment</h2><div class="grid three"><label>Patient Name<input name="patientName" required value="${esc(r.patientName)}"></label><label>Age<input type="number" min="0" max="130" name="age" value="${esc(r.age)}"></label><label>Date of Initial Contact${dateTextInput('initialContactDate',r.initialContactDate)}</label><label class="span-2">Referral Source<input name="referralSource" value="${esc(r.referralSource)}"></label><label>Exam Type<input name="examType" value="${esc(r.examType)}"></label><label>Exam Scheduled${dateTextInput('examScheduled',r.examScheduled)}</label><label>Parent Meeting${dateTextInput('parentMeeting',r.parentMeeting)}</label></div><h2>Deposit</h2><div class="grid two"><label>Deposit needed?<select name="depositNeeded"><option value=""></option><option value="YES" ${r.depositNeeded==='YES'?'selected':''}>YES</option><option value="NO" ${r.depositNeeded==='NO'?'selected':''}>NO</option></select></label><label>Deposit taken?<input name="depositTaken" value="${esc(r.depositTaken)}" placeholder="Blank, YES, NO/FES, or a comment"></label></div><div class="quick-values"><span>Quick values:</span><button type="button" class="chip" data-edit-deposit="YES">YES</button><button type="button" class="chip" data-edit-deposit="NO/FES">NO/FES</button><button type="button" class="chip" data-edit-deposit="">Clear</button></div><div class="form-actions"><button type="button" class="btn btn-ghost" id="cancelInitialEdit2">Cancel</button><button type="submit" class="btn btn-primary">Save Changes</button></div></form></div>`;
  document.getElementById('cancelInitialEdit').onclick=()=>renderInitialTrackingDetail(rowNumber);document.getElementById('cancelInitialEdit2').onclick=()=>renderInitialTrackingDetail(rowNumber);document.querySelectorAll('[data-edit-deposit]').forEach(b=>b.onclick=()=>document.querySelector('[name=depositTaken]').value=b.dataset.editDeposit);document.getElementById('initialTrackingEdit').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());try{normalizeDates(payload,[['initialContactDate','Date of Initial Contact'],['examScheduled','Exam Scheduled'],['parentMeeting','Parent Meeting']])}catch(err){showToast(errorMessage(err),'error');return}try{await window.clinicAPI.updateInitialTracking(rowNumber,payload);showToast('Tracking updated in Excel.');renderInitialTrackingDetail(rowNumber)}catch(err){showToast(errorMessage(err),'error')}};
}


function renderInitialQuickAdd(){
  setHeader('Initial Contact and Patient Tracking','+ New Initial Contact',renderInitialForm);
  appEl.innerHTML=`<div class="form-shell"><div class="section-heading"><div><a class="back" id="backQuickInitial">← Back to Initial Contact and Patient Tracking</a><h1>Add Patient to Tracking Only</h1><p class="muted">Use this when the patient needs to be added to the monthly Excel without completing or generating the Initial Contact PDF.</p></div></div><form id="quickInitialForm" class="form-card"><h2>Patient & Appointment</h2><div class="grid three"><label>Patient Name *<input name="patientName" required></label><label>Age<input type="number" min="0" max="130" name="age"></label><label>Date of Initial Contact${dateTextInput('initialContactDate','',true)}</label><label class="span-2">Referral Source<input name="referralSource"></label><label>Exam Type<input name="examType"></label><label>Exam Scheduled${dateTextInput('examScheduled')}</label><label>Parent Meeting${dateTextInput('parentMeeting')}</label></div><h2>Deposit</h2><div class="grid two"><label>Deposit needed?<select name="depositNeeded"><option value=""></option><option value="YES">YES</option><option value="NO">NO</option></select></label><label>Deposit taken?<input name="depositTaken" placeholder="Blank, YES, NO/FES, or a comment"></label></div><div class="quick-values"><span>Quick values:</span><button type="button" class="chip" data-quick-deposit="YES">YES</button><button type="button" class="chip" data-quick-deposit="NO/FES">NO/FES</button><button type="button" class="chip" data-quick-deposit="">Clear</button></div><div class="form-actions"><button type="button" class="btn btn-ghost" id="cancelQuickInitial">Cancel</button><button type="submit" class="btn btn-primary">Add to Excel</button></div></form></div>`;
  document.getElementById('backQuickInitial').onclick=renderInitialLanding;
  document.getElementById('cancelQuickInitial').onclick=renderInitialLanding;
  document.querySelectorAll('[data-quick-deposit]').forEach(b=>b.onclick=()=>document.querySelector('[name=depositTaken]').value=b.dataset.quickDeposit);
  document.getElementById('quickInitialForm').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());try{normalizeDates(payload,[['initialContactDate','Date of Initial Contact'],['examScheduled','Exam Scheduled'],['parentMeeting','Parent Meeting']])}catch(err){showToast(errorMessage(err),'error');return}try{const res=await window.clinicAPI.saveInitialTracking(payload);showToast(`Patient added to Excel row ${res.rowNumber}.`);renderInitialLanding()}catch(err){showToast(errorMessage(err),'error')}};
}

function checkbox(name,label){return `<label class="check-option"><input type="checkbox" name="${name}"><span>${label}</span></label>`}
function radio(name,value,label){return `<label class="check-option"><input type="radio" name="${name}" value="${esc(value)}"><span>${label}</span></label>`}
function collectForm(form){const fd=new FormData(form),o={};for(const [k,v] of fd.entries())o[k]=v;form.querySelectorAll('input[type=checkbox]').forEach(el=>o[el.name]=el.checked);return o}
function initialScriptLibraryHtml(){return `<section id="initialScriptsPane" class="initial-script-library" hidden><div class="script-library-head"><div><h2>Initial Contact Script Library</h2><p class="muted">Standard Initial Contact is the primary workflow. Use the alternate scripts only when the patient's situation calls for them.</p></div></div><div class="script-selector"><button type="button" class="script-choice active" data-initial-script="standard">Standard Initial Contact</button><button type="button" class="script-choice" data-initial-script="concussion">Concussion / TBI</button><button type="button" class="script-choice" data-initial-script="amblyopia">Amblyopia</button></div>
<div class="script-library-panel" data-script-panel="standard"><h3>Standard Initial Contact</h3><p class="script-note">This is the primary script and is also integrated directly into the Initial Contact Form.</p><details open><summary>Insurance opener</summary><p>I will be happy to talk with you about that but insurance coverage depends on the type of vision evaluation your child may need. Would it be alright with you if I asked you some questions first?</p></details><details><summary>Introduce the office</summary><p>Well, just to give you a background of our practice: We have two doctors here, Dr. Jenna McDermed and Dr. Chi Tran. They are both board certified developmental Optometrist’s. They both specialize in the diagnosis and treatment of vision problems that interfere with reading and learning, as well as non-surgical treatment of eye turns and lazy eyes. Most importantly they do specialized testing that addresses many underlying vision disorders that are not tested for in basic eye exams. Essentially, other doctors and specialists send their patients to our doctors when they see an area of concern that would require this type of specialized testing.</p></details><details><summary>Deposit</summary><p>In order to reserve the 3 hours of time, which includes the two hours of evaluation &amp; one hour doctor consultation, I need to take a non-refundable deposit of $50. If for some reason you need to cancel, as long as you reschedule, the deposit will be credited towards any services. What phone number would you like me to text the clickable invoice to?</p></details></div>
<div class="script-library-panel" data-script-panel="concussion" hidden><h3>Concussion / TBI Initial Contact</h3>
<details open><summary>Text before calling</summary><p>Dr. Mbeo referred you to our office for an evaluation to determine how we can help with your recovery. I will be calling you shortly for your convenience to schedule that appointment. If now isn’t a good time, please text me some times/days that will work for you. This is Amia from Drs. McDermed &amp; Tran’s office.</p></details>
<details open><summary>Once on the phone</summary><p>Repeat the above and then move into the telephone intake form. Ask the patient’s understanding of why they were referred: “What did the doctor say as to why he/she was referring you here?”</p><p>Based on what you have shared with me, I need to gather more information and discuss what is involved in the testing. Before I get started do you have any specific questions? Aside from insurance.</p><p>Good questions. I will answer all of those during this call. However, this can take from 20 to 30 minutes. Is this still a good time for you?</p></details>
<details><summary>If caller is uncertain why they were referred</summary><p>First, you mentioned that you are uncertain why you were referred to our office.</p><p>Most people don’t realize that the majority of people who experience a concussion/head injury/stroke/neurological problems have a variety of different problems that are caused by vision problems that resulted from the concussion/head injury/stroke. In addition, in many cases, if these vision problems aren’t identified and treated, the overall recovery process can be slowed down dramatically. For example, we have seen a number of people who had struggled for years before they came here, and our doctors have been able to help.</p><p>Typically it requires more in-depth testing than a regular eye exam to identify these vision problems and to determine the best course of treatment.</p><p>Our doctors have been able to help a lot of patients who were told nothing else could be done to help people who struggled with maintaining their balance while walking, as well as had trouble with reading or working on a computer to mention a few things. You can add in headaches or other symptoms discussed by the patient.</p><p>You were referred here to have one of our doctors determine if a vision problem is contributing to your/your spouse challenges resulting from the concussion or whatever the patient experienced prior to the symptoms starting. Pause, then ask: Does this make sense to you? Do you have any questions so far?</p></details>
<details><summary>Continue with scheduling</summary><p>You’ve called the right place. Based on what you/your spouse is experiencing, the best thing to do is to schedule an evaluation with one of our doctors.</p><p>The evaluation takes about approx. 2 hours. There is a separate appointment after that with you and anyone involved in your life and care to review the results and treatment options with the doctor. It is best if you can bring someone with you as the doctor will be providing a lot of information, and patients often appreciate having someone with them.</p><p>The total fee is $490.00.</p><p>If they have an attorney or need to talk with an attorney about payment, ask whether the attorney has paid for other medical appointments. If yes: for your convenience, we can send an email to your attorney with all the information and an invoice prior to the appointment to get authorization for the appointment. But in the meantime, we need to get you on the schedule because the doctors’ schedule fills up very quickly.</p><p>Our first available appointment for the evaluation is ____________ (at least 3 weeks out to ensure enough time to receive payment). When would be the best day of the week for you to come in for the evaluation? Schedule the evaluation and consultation appointment.</p><p>If attorney: Please keep in mind, payment is due prior to the appointment, but we will reach out to you if we have any difficulties working with your attorney.</p></details>
<details><summary>Financial concerns</summary><p>I understand that the cost of the appointment can be concerning, but do know that we have successfully treated many patients with symptoms very similar to yours. It is important that you come in for the evaluation so the doctor can determine the depth of the vision problem and to what degree the vision problem is causing the chief concerns/symptoms. In addition, the doctor will discuss all treatment options with you. As I mentioned, our first available appointment for the evaluation is ____________ with Dr. ___________. Is there a better day for you to come in?</p></details>
<details><summary>Prepare the patient for next step</summary><p>We have a Questionnaire that the doctor requires to be filled out prior to your first appointment. I will email you a link to our patient portal where you can fill out this questionnaire online. Please check your spam folders if you do not receive the email, and contact our office if you have difficulty filling it out.</p><p>What is your email address?</p><p>If we do not receive this questionnaire in advance you will need to come in 30 minutes prior to your appointment to fill out a paper copy prior to your appointment. If you do not arrive early the doctor may not have time to complete your full evaluation. Please also Fax/Email/Bring any previous vision records, eyeglasses, and relevant professional reports.</p><p>Any other questions or any questions I didn’t answer?</p></details>
<details><summary>If patient says they will call back</summary><p>OK, our schedule fills up very quickly. I would recommend we get you scheduled, since I can’t promise that this appointment will still be available when you call back. If you need to reschedule to a different time, that’s OK, but I want to make sure you don’t have to wait longer than necessary. Is it OK if I give you a call back tomorrow to see if this appointment still works for you? Which is better for you a phone call or a text message?</p></details>
<details><summary>If patient chooses not to schedule</summary><p>I will keep your information on file. IF REFERRED – I will also notify Dr._____ (referral source) of your decision. However, please know we are here if you change your mind.</p><p><strong>Reason patient did not schedule:</strong> document the reason.</p></details></div>
<div class="script-library-panel" data-script-panel="amblyopia" hidden><h3>Amblyopia Calls</h3>
<details open><summary>Opening</summary><p>Since this is the first time you are hearing that your child has lazy eye, what’s your understanding of what lazy eye is? Or what did your doctor tell you?</p><p><strong>Ask for symptoms.</strong></p><p>If no symptoms: That’s great that you aren’t currently seeing any problems because those are often problems children can have who have lazy eye.</p></details>
<details open><summary>Next — even if the patient has symptoms</summary><p>Left untreated, Lazy eye can cause a variety of problems including permanent loss of vision in the effected eye, you really need to schedule an appointment so the doctor can determine the depth of the problem and review treatment options with you as well. Because your eye doctor referred you here, we are assuming the problem is significant enough that it warrants treatment and referred you here because we specialize in treating these types of vision problems. The best thing to do is to schedule the evaluation, when is the best time…. (Schedule the appointment)</p></details>
<details><summary>Basic information you can use as needed to help educate parents</summary><p>Amblyopia is often referred to as Lazy Eye. It is a condition where one eye is reduced and it cannot be corrected with contacts or glasses. Even though the eyes may be looking at the same image, the brain does not process the visual information as well from the amblyopic eye.</p><p>It can be caused either from an eye turn (strabismus) or a significant difference in prescription between the two eyes. When there is an eye turn the two eyes are looking at different images, causing double vision. To fix this the brain will ignore (suppress) one of the images. Over time this leads to amblyopia.</p><p><strong>Slower reading rates:</strong> Studies have shown that children with amblyopia read significantly slower than those without amblyopia.</p><p><strong>Tracking ability:</strong> is reduced. It is more difficult for the amblyopic eye to track words on a page or to follow a ball when playing a sport.</p><p><strong>Eye focusing:</strong> is decreased and less accurate. This can affect the ability to copy from the board and can cause difficulty with sustained reading and near work.</p><p><strong>3-D vision, or depth perception:</strong> is affected. It can impact balance and movement; for example, kids with poor depth perception are often described as clumsy.</p><p>Treatment usually consists of wearing glasses and if necessary, patching or eye drops, and vision therapy. The purpose of the glasses is to ensure a clear, crisp image projected on the eye. Patching or eye drops are then added to force the “weaker” eye to be utilized more.</p><p>Older kids, parents are often more concerned or motivated by: wanting to drive but poor depth perception causing problems; improving sports performance; no 3D vision / poor depth perception; tired of patching after treating it for years.</p></details></div></section>`}
function wireInitialScriptLibrary(){const formBtn=document.getElementById('initialTabForm'),scriptsBtn=document.getElementById('initialTabScripts'),formPane=document.getElementById('initialFormPane'),scriptsPane=document.getElementById('initialScriptsPane');if(!formBtn||!scriptsBtn)return;const show=(scripts)=>{formPane.hidden=scripts;scriptsPane.hidden=!scripts;formBtn.classList.toggle('active',!scripts);scriptsBtn.classList.toggle('active',scripts)};formBtn.onclick=()=>show(false);scriptsBtn.onclick=()=>show(true);document.querySelectorAll('[data-initial-script]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-initial-script]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('[data-script-panel]').forEach(p=>p.hidden=p.dataset.scriptPanel!==btn.dataset.initialScript)})}

function renderInitialForm(prefill={}){
  setHeader('Initial Contact and Patient Tracking');generatedInitialPdf=null;
  const today=usDateValue(new Date().toISOString().slice(0,10));
  appEl.innerHTML=`<div class="initial-form-shell"><div class="section-heading"><div><h1>New Initial Contact</h1><p class="muted">The standard script stays integrated with the form. Alternate scripts are available without losing anything you have already entered.</p></div></div><div class="initial-work-tabs"><button type="button" id="initialTabForm" class="initial-work-tab active">Initial Contact Form</button><button type="button" id="initialTabScripts" class="initial-work-tab">Scripts</button></div><div id="initialFormPane"><form id="initialForm">
  <section class="paper-page"><div class="paper-brand"><img src="clinic-logo.png" alt="Visual Health & Learning Center"></div><h2 class="paper-title">Initial Contact Form</h2>
    <div class="paper-grid"><label>Date<input type="text" class="us-date" inputmode="numeric" autocomplete="off" placeholder="MM/DD/YYYY" name="date" value="${esc(prefill.date?usDateValue(prefill.date):today)}" required></label><label class="wide">Patient's name<input name="patientName" required value="${esc(prefill.patientName||'')}"></label><label>Age<input type="number" min="0" max="130" name="age" value="${esc(prefill.age||'')}"></label><label>D.O.B.${dateTextInput('dob',prefill.dob||'')}</label><label class="wide">Parent's name<input name="parentName" value="${esc(prefill.parentName||'')}"></label><label>Phone<input name="phone" value="${esc(prefill.phone||'')}"></label><label>Email Address<input type="email" name="email" value="${esc(prefill.email||'')}"></label><label>Grade<select name="grade"><option value=""></option>${['Preschool','PreKindergarten','Kindergarten','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th','11th','12th','College'].map(x=>`<option ${prefill.grade===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="span-all">How did you hear of our office (Who referred you):<input name="referralSource" value="${esc(prefill.referralSource||'')}"></label></div>
    <p class="script-line"><strong class="red">DO YOU TAKE MY INSURANCE?</strong> I will be happy to talk with you about that but insurance coverage depends on the type of vision evaluation your child may need. Would it be alright with you if I asked you some questions first?</p>
    <h3 class="paper-section-title">DOCTOR Referral</h3><p class="script-line"><strong>What did the doctor say as to why referring?</strong></p><div class="check-row">${checkbox('doctorAmblyopia','Amblyopia')}${checkbox('doctorStrabismus','Cross Eye (Strabismus)')}${checkbox('doctorConvergence','Convergence Insufficiency')}</div><div class="question-row"><span>➤ Do you or your child wear glasses or contacts?</span>${radio('glassesContacts','Yes','Yes')}${radio('glassesContacts','No','No')}</div><div class="question-row"><span>➤ Was a new RX given?</span>${radio('newRx','Yes','Yes')}${radio('newRx','No','No')}</div><label class="notes-label">Notes:<textarea name="doctorNotes" rows="5"></textarea></label>
    <h3 class="paper-section-title">NOT A DOCTOR Referral</h3><p class="script-line"><strong>Have you noticed you/child having any problems with school, avoiding homework or reading beyond what you would normally expect for a child his/her age?</strong></p><div class="symptom-grid">${checkbox('sym_school','Suddenly not doing well in school')}${checkbox('sym_losing','Losing place when reading')}${checkbox('sym_tired','Tired when reading')}${checkbox('sym_covers','Covers one eye')}${checkbox('sym_blurry','Blurry vision')}${checkbox('sym_amblyopia','Turned or lazy eye (Amblyopia)')}${checkbox('sym_headaches','Headaches')}${checkbox('sym_close','Holding reading material close')}${checkbox('sym_blinking','Excessive blinking')}${checkbox('sym_adhd','ADHD')}${checkbox('sym_academic','Long standing academic problems')}${checkbox('sym_reversals','Reversals')}${checkbox('sym_bumping','Bumping into things')}${checkbox('sym_trauma','Head trauma/injury')}${checkbox('sym_special','Special needs: autistic, CP, downs')}${checkbox('sym_comprehension','Poor reading comprehension')}</div><p class="script-line red"><strong>We hear that a lot. It's common among our patients and we're able to help.</strong></p><label class="notes-label">Notes:<textarea name="nonDoctorNotes" rows="5"></textarea></label>
    <details class="clinical-reference"><summary>Clinical Reference — Conditions & Scheduling Guidance</summary><div class="clinical-reference-body"><div><h4>Vision conditions commonly evaluated / treated</h4><ul><li>Learning-related vision problems</li><li>Convergence insufficiency and other convergence disorders</li><li>Binocular vision dysfunction (difficulty using the two eyes together)</li><li>Eye tracking / oculomotor problems</li><li>Focusing / accommodative dysfunction</li><li>Visual processing delays</li><li>Visual perceptual dysfunction</li><li>Amblyopia (lazy eye)</li><li>Strabismus (eye turn)</li><li>Diplopia (double vision)</li><li>Vision problems related to concussion, stroke, or brain injury</li><li>Visual snow and other neuro-optometric rehabilitation needs</li></ul><p class="reference-goal">Our goal is to identify how the visual system is functioning beyond eyesight alone and determine whether treatment may improve comfort, efficiency, and visual performance.</p></div><table class="reference-table"><thead><tr><th>Condition / Concern</th><th>Quick Guidance</th></tr></thead><tbody><tr><td>Amblyopia</td><td>Common specialty condition</td></tr><tr><td>Strabismus</td><td>Common specialty condition</td></tr><tr><td>Convergence insufficiency</td><td>Common specialty condition</td></tr><tr><td>Diplopia</td><td>Common specialty condition</td></tr><tr><td>Alternating exotropia</td><td>Common specialty condition</td></tr><tr><td>Myopia</td><td>VHLC does not provide myopia-control treatment; see referral section</td></tr><tr><td>Concussion / stroke / brain injury</td><td><strong>Schedule as a VIP appointment</strong></td></tr><tr><td>Visual snow</td><td>VHLC provides NORT (neuro-optometric rehabilitation therapy)</td></tr></tbody></table></div></details>
    <p class="script-block"><strong><u>INTRODUCE THE OFFICE:</u></strong> “Well, just to give you a background of our practice: We have two doctors here, Dr. Jenna McDermed and Dr. Chi Tran. They are both board certified developmental Optometrist’s. They both specialize in the diagnosis and treatment of vision problems that interfere with reading and learning, as well as non-surgical treatment of eye turns and lazy eyes. Most importantly they do specialized testing that addresses many underlying vision disorders that are not tested for in basic eye exams. Essentially, other doctors and specialists send their patients to our doctors when they see an area of concern that would require this type of specialized testing.”</p>
  </section>
  <section class="paper-page"><h2 class="paper-title">Appointment Scheduling</h2>
    <div class="script-box"><p><strong><u>99203 Young Child (0-4 years of age) or High Support Needs (age doesn’t matter):</u></strong> Based on the information you've given me, you have called the right place. You need to schedule a comprehensive evaluation with Dr. McDermed/Dr. Chi. This is a one hour appointment with Dr. McDermed/Dr. Chi. The doctor will be evaluating the overall health of your/your child's eyes, how the eyes move, checking if there is a need for a new prescription, and most importantly covering the areas of concern that we have just discussed. The fee for this evaluation is $130, do you prefer morning or afternoon?</p><div class="appointment-grid"><label>Exam Type<select name="youngExamType"><option value=""></option><option>Young Child</option><option>Low Functioning</option></select></label><label>Date${dateTextInput('youngExamDate')}</label><label>Time${timeTextInput('youngExamTime')}</label>${checkbox('youngWaitingList','Waiting List')}</div></div>
    <div class="or-divider">OR</div>
    <div class="script-box"><p><strong><u>VDE – VIP:</u></strong> Based on what you have told me, you have called the right place. You need to schedule a Developmental Vision Evaluation. During this appointment, the doctor will be evaluating all the underlying visual skills required for reading and learning which could cause the type of symptoms that you are observing. The evaluation is very in-depth and takes about two hours to complete. The first part of testing will be performed by a technician, and the second part will be performed by the doctor. The consultation is scheduled in a separate appointment a week after the testing is completed and the meeting is with you and all parents or grandparents to ensure all information is taken into account in designing your child’s treatment plan. The fee for both appointments, including the report is $490.00.</p><p>The testing needs to be performed in the morning, because the doctor needs to see how your vision is functioning at that time day. Is there a particular day of the week that would be better for you? (Schedule the appointment.) The parent consultation takes about an hour to 1.5 hour. As I said, it is important to understand that both/all parents need to be there for this appointment. The doctor needs to ask both parents questions privately (not in front of your child). When is the best time for both you and your child’s father to come in to speak with the doctor? (Schedule the consultation.)</p><div class="appointment-grid"><div class="field-group"><span class="mini-label">Doctor</span><div class="check-row">${radio('doctor','Dr. McDermed','Dr. McDermed')}${radio('doctor','Dr. Chi','Dr. Chi')}</div></div><label>Exam Type<select name="devExamType"><option value=""></option><option>VDE</option><option>VIP</option></select></label><label>Exam Date${dateTextInput('devExamDate')}</label><label>Exam Time${timeTextInput('devExamTime')}</label><label>Parent Meeting Date${dateTextInput('parentMeetingDate')}</label><label>Parent Meeting Time${timeTextInput('parentMeetingTime')}</label>${checkbox('devWaitingList','Waiting List')}</div></div>
    <h3>Closing the Phone Call:</h3><p class="script-block">It’s important to remember that we have reserved 2 hours for the testing appointment, so it is important for you to arrive on time. There is some paperwork which will be needed prior to the appointment. It is 6 pages long, so if you don’t have time to fill this in prior to the appointment you will need to come 15 minutes before your scheduled appointment so you can fill it out.</p><p class="highlight-script">Which email address would you like me to send it to?</p><p class="script-block">In order to reserve the 3 hours of time, which includes the two hours of evaluation & one hour doctor consultation, I need to take a non-refundable deposit of $50. If for some reason you need to cancel, as long as you reschedule, the deposit will be credited towards any services. What phone number would you like me to text the clickable invoice to?</p>
    <div class="credit-card-grid"><label>Credit Card Type<select name="cardType"><option value=""></option><option>Visa</option><option>Mastercard</option><option>American Express</option><option>Discover</option></select></label><label>Credit Card Number<input name="cardNumber"></label><label>Expiration Date<input name="cardExpiration" placeholder="MM/YY"></label><label>Cardholder's Name<input name="cardholderName"></label><label>Cardholder's Zip Code<input name="cardZip"></label><label>Code on back of card<input name="cardCode"></label></div>
    <ul class="closing-list"><li>Thank you for all that information! You will receive two emails from us. One with your receipt and a second will include the paperwork we discussed & the address to our facility with some helpful tips to keep you from getting lost when you arrive.</li><li>Before we go, do you have any other questions?</li><li>Alright great!! So just to recap, your appointments are scheduled for: (recap appointment dates/times)</li><li>We will email you the week before and call the day before your appointment to remind you. Other than that, I hope you have a great day and we will see you soon!!!</li></ul>
  </section>
  <section class="paper-page"><h2 class="paper-title left">IF CALLER ASKS:</h2><p class="script-block"><strong>Insurance:</strong> Our doctors are considered private pay or out-of-network providers for all insurances. All fees and payments are due at the time of service.</p><ul class="caller-list"><li>Keep in mind that insurance companies vary on what they cover and what they don’t; every plan is different. The initial evaluation may be covered if you have out-of-network benefits. We will provide you with a receipt so you may submit to your insurance company for reimbursement.</li><li>We provide many different types of vision therapy, such as specialized eyeglasses, home exercises, or in-office programs. So the best thing to do is to schedule the evaluation and then the doctor can give you more details.</li></ul><p class="script-block"><strong>Financial Concerns about the Appointment:</strong> It’s more important that you come in for the evaluation so the doctor can figure out the depth of the visual problem and discuss all treatment options with you.</p><p class="script-block"><strong>Asking about Vision Therapy program:</strong> The length of the program and the fees really vary, depending on the depth of the visual problem. We provide many different types of vision therapy, such as specialized eyeglasses, home exercises, or in-office programs. The doctor will discuss all treatment options after the evaluation. <strong>IF THE PARENT IS NOT SATISFIED WITH THIS ANSWER AND REALLY WANTS THE COST FOR VT</strong> – the fee per session is $<input class="inline-input" name="vtCostPerSession">, the length of the program depends on the actual vision problem. The best thing to do would be to schedule the evaluation so the doctor can figure out what is going on and determine your best treatment options. When is the best time for you to come in?</p><p class="script-block"><strong>Refuses to give cc over the phone:</strong><br>No problem. We can send you a digital invoice, and you can pay the invoice online. However, we can only hold the appointment for 24 hours, and we will have to release if you haven’t been able to pay the deposit.</p><p class="script-block"><strong>Doesn’t want to pay by cc:</strong><br>You are welcome to drop off payment. Generally, we can only hold a spot for 24 hours, but I understand you may not be able to get here that soon. When do you think you can drop it off?<br>No problem, I can hold the spot until then. Call me if there’s any difficulties.</p></section>
  <div class="sticky-form-actions"><button type="button" class="btn" id="cancelInitial">Cancel</button><button type="submit" class="btn btn-primary">Generate PDF & Continue →</button></div></form></div>${initialScriptLibraryHtml()}</div>`;
  wireInitialScriptLibrary();
  document.getElementById('cancelInitial').onclick=renderInitialLanding;
  document.getElementById('initialForm').onsubmit=async e=>{e.preventDefault();const data=collectForm(e.currentTarget);try{normalizeDates(data,[['date','Date'],['dob','D.O.B.'],['youngExamDate','Young Child Exam Date'],['devExamDate','Exam Date'],['parentMeetingDate','Parent Meeting Date'],['waitlistDate','Waitlist Date']]);normalizeTimes(data,[['youngExamTime','Exam Time'],['devExamTime','Exam Time'],['parentMeetingTime','Parent Meeting Time']])}catch(err){showToast(errorMessage(err),'error');return}currentInitialForm=data;try{const result=await window.clinicAPI.generateInitialPdf(data);if(!result)return;generatedInitialPdf=result;showToast('PDF generated. Complete the tracking fields.');renderInitialTracking(data,result)}catch(err){showToast(errorMessage(err),'error')}};
}

function renderInitialTracking(data,pdf){setHeader('Initial Contact and Patient Tracking');const examDate=data.devExamDate||data.youngExamDate||'',examType=normalizeExamType(data.devExamType)||data.youngExamType||'',parentMeeting=data.parentMeetingDate||'';appEl.innerHTML=`<div class="form-shell"><div class="section-heading"><div><a class="back" id="backInitial">← Back to form</a><h1>Deposit Tracking</h1><p class="muted">The PDF is complete. Review the fields that will be written to the tracking Excel and fill only the additional deposit information.</p></div><button class="btn" id="openGeneratedPdf">Open Generated PDF</button></div><form id="trackingForm" class="form-card"><h2>From Initial Contact Form</h2><div class="grid three"><label>Patient Name<input name="patientName" value="${esc(data.patientName)}" readonly></label><label>Age<input name="age" value="${esc(data.age)}" readonly></label><label>Date of Initial Contact${dateTextInput('initialContactDate',data.date)}</label><label class="span-2">Referral Source<input name="referralSource" value="${esc(data.referralSource)}"></label><label>Exam Scheduled${dateTextInput('examScheduled',examDate)}</label><label>Exam Type<input name="examType" value="${esc(examType)}"></label><label>Parent Meeting${dateTextInput('parentMeeting',parentMeeting)}</label></div><h2>Additional Tracking Information</h2><div class="grid two"><label>Does the patient need a deposit?<select name="depositNeeded" required><option value="">Select…</option><option value="YES">YES</option><option value="NO">NO</option></select></label><label>Deposit taken?<input name="depositTaken" placeholder="Leave blank, YES, NO/FES, or enter a comment"></label></div><div class="quick-values"><span>Quick values:</span><button type="button" class="chip" data-deposit="YES">YES</button><button type="button" class="chip" data-deposit="NO/FES">NO/FES</button><button type="button" class="chip" data-deposit="">Clear</button></div><div class="form-actions"><button type="button" class="btn" id="cancelTracking">Cancel</button><button type="submit" class="btn btn-primary">Save to Excel</button></div></form></div>`;document.getElementById('backInitial').onclick=()=>renderInitialForm(currentInitialForm||{});document.getElementById('openGeneratedPdf').onclick=()=>window.clinicAPI.openGeneratedPdf(pdf.localPath).catch(e=>showToast(errorMessage(e),'error'));document.getElementById('cancelTracking').onclick=renderInitialLanding;document.querySelectorAll('[data-deposit]').forEach(b=>b.onclick=()=>document.querySelector('[name=depositTaken]').value=b.dataset.deposit);document.getElementById('trackingForm').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());try{normalizeDates(payload,[['initialContactDate','Date of Initial Contact'],['examScheduled','Exam Scheduled'],['parentMeeting','Parent Meeting']])}catch(err){showToast(errorMessage(err),'error');return}try{const res=await window.clinicAPI.saveInitialTracking(payload);let setupRes=null,setupError='';if(examDate){try{setupRes=await window.clinicAPI.addSetupFromInitial(data)}catch(setupErr){setupError=errorMessage(setupErr)}}showToast(setupError?`Payment tracking saved, but New Patient Setup could not be added: ${setupError}`:(examDate?'Saved to Excel and added automatically to New Patient Setup.':'Saved to Excel. No scheduled exam was found, so New Patient Setup was not created.'),setupError?'error':'success');renderInitialSuccess(payload,pdf,res,setupRes,setupError)}catch(err){showToast(errorMessage(err),'error')}}}
function renderInitialSuccess(data,pdf,res,setupRes=null,setupError=''){setHeader('Initial Contact and Patient Tracking','+ New Initial Contact',renderInitialForm);appEl.innerHTML=`<section class="success-panel"><div class="success-icon">✓</div><h1>Initial Contact Completed</h1><p><strong>${esc(data.patientName)}</strong> was added to the deposit tracking spreadsheet${setupRes?' and the New Patient Setup checklist':''}.</p>${setupError?`<div class="flash error">New Patient Setup could not be created automatically: ${esc(setupError)}</div>`:''}<div class="success-details"><div><span>Excel row</span><strong>${res.rowNumber}</strong></div><div><span>Worksheet</span><strong>${esc(res.worksheet)}</strong></div><div class="wide"><span>PDF</span><strong>${esc(pdf.exportedPath)}</strong></div></div><div class="inline-actions center"><button class="btn" id="openPdfSuccess">Open PDF</button><button class="btn btn-primary" id="newInitialSuccess">New Initial Contact</button><button class="btn" id="initialHomeSuccess">Patient Tracking Home</button></div></section>`;document.getElementById('openPdfSuccess').onclick=()=>window.clinicAPI.openGeneratedPdf(pdf.localPath);document.getElementById('newInitialSuccess').onclick=renderInitialForm;document.getElementById('initialHomeSuccess').onclick=renderInitialLanding}


