const CANCELLATION_STATUSES=['Follow-up','Awaiting 2nd Contact','Awaiting 3rd Contact','Rescheduled','Will Not Reschedule','No Answer After 3 Attempts'];
function cancellationScriptPanel(patientName=''){const child=patientName||'[Child’s Name]';return `<section class="script-workflow-card">
  <div class="script-workflow-head"><div><h2>Cancellation / No-Show Script</h2><p class="muted small">Use this policy when the same exam has been cancelled or no-showed for the second time in a row.</p></div></div>
  <div class="policy-note"><strong>Policy:</strong> When a patient cancels or no-shows for an exam for the second time in a row, we generally require full payment for the appointment in order to reschedule. In the case of a Parent Conference (PC), we may require an additional fee before rescheduling.</div>
  <div class="spoken-script"><span class="script-label">What to say when they call to cancel the second appointment</span><p>“Of course, I can cancel that appointment for you. I did want to let you know that this is the second time this particular appointment has been cancelled. Because we reserve a significant amount of time specifically for your appointment, if you would like to reschedule, we will need to collect the full non-refundable appointment fee in order to reschedule.”</p></div>
  <p class="muted small"><strong>If the patient already no-showed:</strong> explain the policy when they call back to reschedule. The goal is to politely explain the policy, set expectations before another appointment is reserved, and make sure they are committed to coming next time.</p>
  <p class="muted small"><strong>If you are unsure whether the policy applies:</strong> ask before rescheduling the patient or collecting payment.</p>
</section>`}
function followUpScriptPanel(patientName=''){const child=patientName||'[Child’s Name]';return `<section class="script-workflow-card">
  <div class="script-workflow-head"><div><h2>Follow-Up Script for Cancelled VDE / VIP</h2><p class="muted small">For families who cancelled within the past two months and did not reschedule.</p></div></div>
  <div class="review-checklist"><strong>Before calling, review the Initial Contact Form in Crystal:</strong><ul><li>Child's name</li><li>Specific problems or symptoms originally reported</li><li>Who referred them, if applicable</li><li>Any other relevant information from the initial call</li></ul></div>
  <details open><summary>1. Text Before Calling</summary><div class="spoken-script"><p>“Hi, this is Julia from the Visual Health &amp; Learning Center. I'm going to be calling you shortly to assist with rescheduling your appointment with us. If now is not a good time, please let me know when you would be available to talk. Thank you so much.”</p></div></details>
  <details open><summary>Phone Call</summary><div class="spoken-script"><p>“Hi, this is Julia calling from Visual Health &amp; Learning Center. I’m reaching out about rescheduling <strong>[Child’s Name]</strong>’s vision evaluation. When you originally contacted us, you mentioned that <strong>[Child’s Name] was having difficulty with __________</strong>. I wanted to check in and see if that is still something you’re noticing or concerned about.”</p><p>If they were referred, add:</p><p>“I also see that <strong>Dr. ________ at ________ referred [Child’s Name]</strong> to our office for an evaluation.”</p><p>Then explain:</p><p>“Our doctors asked me to reach out to some of the families who weren’t able to complete their evaluations to see how the children are doing and whether we can help get them evaluated.”</p></div></details>
  <details><summary>Voicemail</summary><div class="spoken-script"><p>“Hi, this is Julia calling from Visual Health &amp; Learning Center regarding <strong>[Child’s Name]</strong>. Our doctors asked me to follow up with you about the vision evaluation you had previously scheduled with our office. We wanted to check in and see how [Child’s Name] is doing and whether we can help get the evaluation rescheduled. Please give me a call back at 407-277-5729. Again, this is Julia from Visual Health &amp; Learning Center. We look forward to speaking with you.”</p></div></details>
  <p class="muted small"><strong>Important:</strong> review the Initial Contact Form before each call so the follow-up feels personalized and reflects the family's original concerns.</p>
</section>`.split('[Child’s Name]').join(esc(child))}
function cancellationStateClass(state){return state==='Rescheduled'?'status-scheduled':state==='Will Not Reschedule'||state==='No Answer After 3 Attempts'?'status-closed':'status-warning'}
async function renderCancellationLanding(){
  setHeader('Exam Cancelations','+ New Cancellation',()=>renderCancellationForm());
  appEl.innerHTML=`<section class="hero-row"><div><h1>Exam Cancelations</h1><p class="muted">Track cancellations and no-shows, document the reason, and keep families who still need rescheduling follow-up at the top of the work queue.</p></div></section><div class="card"><p class="muted">Loading cancellation tracking…</p></div>`;
  let info,result;try{[info,result]=await Promise.all([window.clinicAPI.getCancellationInfo(),window.clinicAPI.listCancellations()])}catch(e){fatal(e,renderCancellationLanding);return}
  const recs=result.records||[];const active=recs.filter(r=>r._state==='Follow-up');const closed=recs.filter(r=>r._state!=='Follow-up');
  appEl.innerHTML=`<section class="hero-row"><div><h1>Exam Cancelations</h1><p class="muted">Track cancellations and no-shows, document the reason, and keep families who still need rescheduling follow-up at the top of the work queue.</p></div><button class="btn btn-primary" id="newCancellationInline">+ New Cancellation</button></section>
  <section class="card workbook-strip"><div class="section-title-row"><div><h2>Tracking Spreadsheet</h2><p class="muted small">Change the file whenever the clinic starts a new monthly spreadsheet.</p></div><div class="inline-actions"><button class="btn" id="chooseCancellationWorkbook">Choose / Change Excel</button>${info.usingSimulation?'':`<button class="btn btn-ghost" id="useCancellationSimulation">Use Simulation</button>`}</div></div><div class="workbook-meta"><div><span>Current file</span><strong class="path-text">${esc(info.workbookPath)}</strong></div><div><span>Worksheet</span><strong>${esc(info.analysis.worksheet)}</strong></div><div><span>Header row</span><strong>${info.analysis.headerRow}</strong></div><div><span>Mode</span><strong>${info.usingSimulation?'SIMULATION':'CONNECTED'}</strong></div></div></section>
  <div class="toolbar"><input id="cancelSearch" class="search" type="search" placeholder="Search patient, reason, referral source..."><select id="cancelStatus"><option value="">All statuses</option>${CANCELLATION_STATUSES.map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="btn" id="cancelSearchBtn">Search</button></div>
  <div id="cancellationLists"></div>`;
  document.getElementById('newCancellationInline').onclick=()=>renderCancellationForm();
  document.getElementById('chooseCancellationWorkbook').onclick=async()=>{try{const chosen=await window.clinicAPI.chooseCancellationWorkbook();if(!chosen)return;if(chosen.analysis.score<14){showToast(`Workbook detected, but only ${chosen.analysis.score}/14 expected fields matched.`,'error');return}await window.clinicAPI.connectCancellationWorkbook(chosen.filePath);showToast('Cancellation workbook connected.');renderCancellationLanding()}catch(e){showToast(errorMessage(e),'error')}};
  if(document.getElementById('useCancellationSimulation'))document.getElementById('useCancellationSimulation').onclick=async()=>{await window.clinicAPI.useCancellationSimulation();renderCancellationLanding()};
  const draw=()=>{const q=(document.getElementById('cancelSearch').value||'').trim().toLowerCase(),sf=document.getElementById('cancelStatus').value;const filt=recs.filter(r=>{const h=[r.patientName,r.cancellationReason,r.referralSource,r.examType,r.followUpNotes].join(' ').toLowerCase();return(!q||h.includes(q))&&(!sf||r.followUpStatus===sf||r._state===sf)});const a=filt.filter(r=>r._state==='Follow-up'),c=filt.filter(r=>r._state!=='Follow-up');document.getElementById('cancellationLists').innerHTML=cancellationSection('Follow-up','Contact attempts remaining (up to three).',a,false)+cancellationSection('Closed','Rescheduled, declined or not reached after three attempts.',c,true);document.querySelectorAll('[data-open-cancellation]').forEach(el=>el.onclick=()=>renderCancellationDetail(Number(el.dataset.openCancellation)))};
  document.getElementById('cancelSearchBtn').onclick=draw;document.getElementById('cancelSearch').addEventListener('keydown',e=>{if(e.key==='Enter')draw()});document.getElementById('cancelStatus').onchange=draw;draw();
}
function cancellationSection(title,desc,list,closed){return `<section class="home-section ${closed?'closed-section':''}"><div class="section-title-row"><div><h2>${title}</h2><p class="muted small">${desc}</p></div><span class="count-badge ${closed?'neutral':''}">${list.length}</span></div><div class="table-card"><table><thead><tr><th>Patient</th><th>Exam</th><th>Cancelled / No-Show</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody>${list.length?list.map(r=>`<tr><td><strong>${esc(r.patientName)}</strong><div class="muted small">${esc(r.referralSource||'')}</div></td><td>${esc(r.examType||'—')}<div class="muted small">${fmtDate(r.originalAppointmentDate)}</div></td><td>${esc(r.eventType||'—')}<div class="muted small">${fmtDate(r.cancellationDate)}</div></td><td>${esc(r.cancellationReason||'—')}</td><td><span class="status ${cancellationStateClass(r._state)}">${esc(r._state)}</span></td><td class="right"><a class="link" data-open-cancellation="${r._row}">Open →</a></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No patients in this section.</td></tr>`}</tbody></table></div></section>`}
function cancellationFormFields(r={}){return `<h2>Patient & Original Appointment</h2><div class="grid three"><label>Patient Name *<input name="patientName" required value="${esc(r.patientName||'')}"></label><label>Age<input type="number" min="0" max="130" name="age" value="${esc(r.age||'')}"></label><label>Exam Type<select name="examType"><option value=""></option>${['VDE','VIP','99203','Parent Conference (PC)','Other'].map(x=>`<option ${r.examType===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Original Appointment Date${dateTextInput('originalAppointmentDate',r.originalAppointmentDate||'')}</label><label class="span-2">Referral Source<input name="referralSource" value="${esc(r.referralSource||'')}" placeholder="Doctor / office, personal referral, etc."></label></div>
  <h2>Cancellation / No-Show</h2><div class="grid two"><label>Date${dateTextInput('cancellationDate',r.cancellationDate||'',true)}</label><label>Event Type *<select name="eventType" required><option value=""></option><option ${r.eventType==='Cancelled'?'selected':''}>Cancelled</option><option ${r.eventType==='No-show'?'selected':''}>No-show</option></select></label><label class="checkbox-card"><input type="checkbox" name="secondOccurrence" value="YES" ${String(r.secondOccurrence||'').toUpperCase()==='YES'?'checked':''}><span><strong>Second cancellation / no-show</strong><small>Check only if this is the second time in a row for this appointment.</small></span></label><label class="span-2">Cancellation Reason *<textarea name="cancellationReason" required placeholder="Why did the patient cancel / miss the appointment?">${esc(r.cancellationReason||'')}</textarea></label></div>`}
function renderCancellationForm(rowNumber=null,r={}){
  setHeader('Exam Cancelations');const isEdit=!!rowNumber;if(!isEdit&&!r.cancellationDate)r={...r,cancellationDate:new Date().toISOString().slice(0,10)};appEl.innerHTML=`<div class="form-shell cancellation-form-shell"><div class="section-heading"><div><a class="back" id="backCancellation">← Back to Exam Cancelations</a><h1>${isEdit?'Edit Exam Cancellation':'New Exam Cancellation'}</h1><p class="muted">Document the cancellation. Follow-up is managed later from the patient's profile.</p></div></div>${cancellationScriptPanel(r.patientName)}<form id="cancellationForm" class="form-card">${cancellationFormFields(r)}<div class="form-actions"><button type="button" class="btn btn-ghost" id="cancelCancellation">Cancel</button><button type="submit" class="btn btn-primary">${isEdit?'Save Changes':'Add to Excel'}</button></div></form></div>`;
  document.getElementById('backCancellation').onclick=isEdit?()=>renderCancellationDetail(rowNumber):renderCancellationLanding;document.getElementById('cancelCancellation').onclick=isEdit?()=>renderCancellationDetail(rowNumber):renderCancellationLanding;
  document.getElementById('cancellationForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());data.secondOccurrence=data.secondOccurrence||'NO';try{normalizeDates(data,[['originalAppointmentDate','Original Appointment Date'],['cancellationDate','Cancellation / No-Show Date']])}catch(err){showToast(errorMessage(err),'error');return}try{if(isEdit){await window.clinicAPI.updateCancellation(rowNumber,data);showToast('Cancellation tracking updated in Excel.');renderCancellationDetail(rowNumber)}else{const res=await window.clinicAPI.createCancellation(data);showToast(`Cancellation added to Excel row ${res.rowNumber}.`);renderCancellationLanding()}}catch(err){showToast(errorMessage(err),'error')}};
}
function cancellationContactCount(r){return [1,2,3].filter(n=>!!r['attempt'+n+'At']).length}
function cancellationNextAttempt(r){if(r._state!=='Follow-up')return null;return [1,2,3].find(n=>!r['attempt'+n+'At'])||null}
function cancellationAttemptScript(attempt,r){
  const patient=String(r.patientName||'').trim()||'[Child’s Name]';
  const text="Hi, this is Julia from the Visual Health & Learning Center. I'm going to be calling you shortly to assist with rescheduling your appointment with us. If now is not a good time, please let me know when you would be available to talk. Thank you so much.";
  const call=`Hi, this is Julia calling from Visual Health & Learning Center. I’m reaching out about rescheduling ${patient}’s vision evaluation. When you originally contacted us, you mentioned that ${patient} was having difficulty with __________. I wanted to check in and see if that is still something you’re noticing or concerned about.`;
  const referred=`I also see that Dr. ________ at ________ referred ${patient} to our office for an evaluation.`;
  const closing=`Our doctors asked me to reach out to some of the families who weren’t able to complete their evaluations to see how the children are doing and whether we can help get them evaluated.`;
  const vm=`Hi, this is Julia calling from Visual Health & Learning Center regarding ${patient}. Our doctors asked me to follow up with you about the vision evaluation you had previously scheduled with our office. We wanted to check in and see how ${patient} is doing and whether we can help get the evaluation rescheduled. Please give me a call back at 407-277-5729. Again, this is Julia from Visual Health & Learning Center. We look forward to speaking with you.`;
  return `<div class="contact-script"><h4>${attempt===1?'1st':attempt===2?'2nd':'3rd'} Contact Scripts</h4><p class="muted small">Before calling, review the Initial Contact Form in Crystal to personalize the family’s original concerns.</p>${attempt===1?`<details><summary>Message before first call</summary><div class="script-copy-row"><button type="button" class="copy-btn copy-script-btn" data-copy-text="${encodeURIComponent(text)}">Copy message</button></div><p>${esc(text)}</p></details>`:''}<details open><summary>Phone call</summary><p>${esc(call)}</p><p><strong>If referred, add:</strong> ${esc(referred)}</p><p>${esc(closing)}</p></details><details><summary>Voicemail</summary><p>${esc(vm)}</p></details></div>`;
}

async function renderCancellationDetail(rowNumber){
  setHeader('Exam Cancelations','+ New Cancellation',()=>renderCancellationForm());
  let r;try{r=await window.clinicAPI.getCancellation(rowNumber)}catch(e){fatal(e,renderCancellationLanding);return}if(!r){renderCancellationLanding();return}
  const closed=r._state!=='Follow-up',attempt=cancellationNextAttempt(r);
  appEl.innerHTML=`<div class="detail-head"><div><a class="back" id="backCancellationHome">← Back to Exam Cancelations</a><h1>${esc(r.patientName)}</h1><span class="status ${cancellationStateClass(r._state)}">${esc(r._state)}</span></div><div class="detail-actions"><button class="btn" id="editCancellation">Edit Cancellation</button>${!closed?`<button class="btn btn-primary" id="closeCancellationRescheduled">Mark Rescheduled</button><button class="btn" id="closeCancellationDeclined">Will Not Reschedule</button>`:''}<button class="btn btn-danger" id="deleteCancellation">Delete Patient</button></div></div>
  <div class="detail-grid"><section class="card span-all"><h2>Patient & Cancellation</h2><dl class="facts facts-wide"><div><dt>Age</dt><dd>${esc(r.age||'—')}</dd></div><div><dt>Referral Source</dt><dd>${esc(r.referralSource||'—')}</dd></div><div><dt>Exam Type</dt><dd>${esc(r.examType||'—')}</dd></div><div><dt>Original Appointment</dt><dd>${fmtDate(r.originalAppointmentDate)}</dd></div><div><dt>Event</dt><dd>${esc(r.eventType||'—')} — ${fmtDate(r.cancellationDate)}</dd></div><div><dt>Second Occurrence?</dt><dd>${String(r.secondOccurrence).toUpperCase()==='YES'?'YES':'NO'}</dd></div><div class="full"><dt>Reason</dt><dd>${esc(r.cancellationReason||'—')}</dd></div></dl></section>
  <section class="card span-all"><h2>Contact History</h2><div class="timeline">${[1,2,3].map(i=>`<div class="timeline-item ${r['attempt'+i+'At']?'done':''}"><div class="timeline-dot">${i}</div><div><strong>${i===1?'1st':i===2?'2nd':'3rd'} Contact</strong><div class="muted small">${fmtDateTime(r['attempt'+i+'At'])}</div><div class="comment">${esc(r['attempt'+i+'Comment']||'No comment')}</div></div></div>`).join('')}</div>
  ${attempt?`<form id="cancellationContactForm" class="quick-form"><h3>Add contact attempt ${attempt} of 3</h3>${cancellationAttemptScript(attempt,r)}<label>Date/Time<div class="datetime-with-action"><input id="cancellationContactTime" name="contact_datetime" type="text" autocomplete="off" placeholder="MM/DD/YYYY hh:mm AM/PM" value="${esc(nowUsDateTime())}" required><button type="button" class="btn btn-ghost" id="useNowCancellation">Now</button></div></label><label>Comment<textarea name="comment" rows="3" placeholder="Call outcome, voicemail left, next action..."></textarea></label><button class="btn btn-primary" type="submit">Save Contact${attempt===3?' & Close Case':''}</button></form>`:''}</section>
  <section class="card span-all"><h2>Follow-up Result</h2><dl class="facts facts-wide"><div><dt>Outcome</dt><dd>${esc(r._state)}</dd></div><div><dt>Last Contact</dt><dd>${fmtDate(r.lastFollowUpDate)}</dd></div><div><dt>New Appointment</dt><dd>${fmtDate(r.newAppointmentDate)}</dd></div><div><dt>Closed At</dt><dd>${fmtDateTime(r.closedAt)}</dd></div><div class="full"><dt>Notes</dt><dd>${esc(r.followUpNotes||'—')}</dd></div></dl>${!closed?`<label>Notes<textarea id="cancellationFollowupNotes">${esc(r.followUpNotes||'')}</textarea></label><button class="btn" id="saveCancellationNotes">Save Notes</button>`:''}</section></div>`;
  document.getElementById('backCancellationHome').onclick=renderCancellationLanding;
  document.getElementById('editCancellation').onclick=()=>renderCancellationForm(rowNumber,r);
  document.getElementById('deleteCancellation').onclick=async()=>{if(!confirm(`Delete ${r.patientName} from the currently selected cancellations Excel? A backup will be created first.`))return;try{await window.clinicAPI.deleteCancellation(rowNumber);showToast('Cancellation deleted.');renderCancellationLanding()}catch(e){showToast(errorMessage(e),'error')}};
  const form=document.getElementById('cancellationContactForm');if(form)form.onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form).entries());try{payload.contact_datetime=parseUsDateTime(payload.contact_datetime,'Date/Time');await window.clinicAPI.addCancellationContact(rowNumber,payload);showToast(attempt===3?'Third attempt saved. Case closed.':'Contact attempt saved.');renderCancellationDetail(rowNumber)}catch(err){showToast(errorMessage(err),'error')}};
  const nowBtn=document.getElementById('useNowCancellation');if(nowBtn)nowBtn.onclick=()=>document.getElementById('cancellationContactTime').value=nowUsDateTime();
  wireScriptCopyButtons();
  const notesBtn=document.getElementById('saveCancellationNotes');if(notesBtn)notesBtn.onclick=async()=>{try{await window.clinicAPI.updateCancellation(rowNumber,{followUpNotes:document.getElementById('cancellationFollowupNotes').value});showToast('Notes saved.');renderCancellationDetail(rowNumber)}catch(e){showToast(errorMessage(e),'error')}};
  const rescheduleBtn=document.getElementById('closeCancellationRescheduled');if(rescheduleBtn)rescheduleBtn.onclick=()=>renderCancellationOutcome(rowNumber,r,'Rescheduled');
  const declineBtn=document.getElementById('closeCancellationDeclined');if(declineBtn)declineBtn.onclick=()=>renderCancellationOutcome(rowNumber,r,'Will Not Reschedule');
}
function renderCancellationOutcome(rowNumber,r,outcome){
  setHeader('Exam Cancelations');appEl.innerHTML=`<div class="form-shell"><div class="section-heading"><div><a class="back" id="backCancelOutcome">← Back to ${esc(r.patientName)}</a><h1>${esc(outcome)}</h1></div></div><form class="form-card" id="cancelOutcomeForm"><h2>Close Cancellation Follow-up</h2>${outcome==='Rescheduled'?`<label>New Appointment Date${dateTextInput('newAppointmentDate',r.newAppointmentDate||'',true)}</label>`:''}<label>Notes<textarea name="followUpNotes">${esc(r.followUpNotes||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelOutcomeBack">Cancel</button><button class="btn btn-primary" type="submit">Save & Close</button></div></form></div>`;
  document.getElementById('backCancelOutcome').onclick=()=>renderCancellationDetail(rowNumber);document.getElementById('cancelOutcomeBack').onclick=()=>renderCancellationDetail(rowNumber);
  document.getElementById('cancelOutcomeForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());try{if(outcome==='Rescheduled')normalizeDates(data,[['newAppointmentDate','New Appointment Date']]);await window.clinicAPI.updateCancellation(rowNumber,{...data,followUpStatus:outcome,closureReason:outcome,rescheduled:outcome==='Rescheduled'?'YES':'NO',closedAt:new Date().toISOString()});showToast('Case closed.');renderCancellationLanding()}catch(e){showToast(errorMessage(e),'error')}};
}

// ---------------- New Patient Setup ----------------
function setupTaskPill(label,value){const done=String(value||'').trim().toLowerCase()==='yes';return `<span class="task-mini ${done?'done':''}">${done?'✓':'○'} ${esc(label)}</span>`}
function setupSection(title,desc,list,closed=false){return `<section class="home-section ${closed?'closed-section':''}"><div class="section-title-row"><div><h2>${esc(title)}</h2><p class="muted small">${esc(desc)}</p></div><span class="count-badge ${closed?'neutral':''}">${list.length}</span></div><div class="table-card"><table class="setup-table"><thead><tr><th>Patient</th><th>Scheduled On</th><th>Exam</th><th>Parent / Contact</th><th>Setup Tasks</th><th></th></tr></thead><tbody>${list.length?list.map(r=>`<tr data-open-setup="${r._row}"><td><strong>${esc(r.patientName)}</strong><div class="muted small">DOB ${fmtDate(r.dob)}</div></td><td><strong>${fmtDate(r.scheduledOn)}</strong><div class="muted small">Called ${fmtDate(r.initialContactDate)}</div></td><td>${esc(r.examType||'—')}<div class="muted small">${fmtDate(r.examDate)}${r.examTime?` · ${esc(r.examTime)}`:''}</div></td><td>${esc(r.parentName||'—')}<div class="muted small">${esc(r.phone||r.email||'')}</div></td><td>${setupTaskPill('Add to Crystal',r.addPatientCrystal)}${setupTaskPill('Schedule',r.schedulePatientCrystal)}${setupTaskPill('Email',r.sendInitialEmail)}</td><td class="right"><a class="link" data-open-setup="${r._row}">Open →</a></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No patients in this section.</td></tr>`}</tbody></table></div></section>`}

async function renderSetupLanding(){
  setHeader('New Patient Setup');
  appEl.innerHTML=`<section class="hero-row"><div><h1>New Patient Setup</h1><p class="muted">Complete the operational steps required after a new patient is scheduled.</p></div></section><div class="card"><p class="muted">Loading patient setup tracking…</p></div>`;
  let result;try{result=await window.clinicAPI.listSetup()}catch(e){fatal(e,renderSetupLanding);return}
  const recs=result.records||[];
  const pending=recs.filter(r=>r._state!=='Completed');
  const completed=recs.filter(r=>r._state==='Completed');
  appEl.innerHTML=`<section class="hero-row"><div><h1>New Patient Setup</h1><p class="muted">Patients scheduled through Initial Contact are added here automatically. Complete the Crystal setup and initial email tasks below.</p></div><div class="inline-actions"><button class="btn btn-primary" id="manualSetupAdd">+ Add Patient</button><button class="btn" id="openSetupExcel">Open Excel</button></div></section><div class="setup-workspace"><div class="setup-list-pane"><div class="toolbar"><input id="setupSearch" class="search" type="search" placeholder="Search patient, parent, exam, phone..."><button class="btn" id="setupSearchBtn">Search</button></div><div id="setupLists"></div><div class="data-location">Local setup data: ${esc(result.workbookPath||'')}</div></div><aside class="setup-side-panel" id="setupSidePanel"><div class="setup-empty-panel"><strong>Select a patient</strong><span>Patient information will appear here vertically for quick copy/paste into Crystal.</span></div></aside></div>`;
  const draw=()=>{const q=(document.getElementById('setupSearch').value||'').trim().toLowerCase();const match=r=>!q||[r.patientName,r.parentName,r.phone,r.email,r.examType,r.referralSource].join(' ').toLowerCase().includes(q);document.getElementById('setupLists').innerHTML=setupSection('Needs Setup','Patients with one or more remaining setup tasks.',pending.filter(match),false)+setupSection('Completed','Patients with all three setup tasks completed.',completed.filter(match),true);document.querySelectorAll('[data-open-setup]').forEach(el=>el.onclick=e=>{e.stopPropagation();renderSetupSidePanel(Number(el.dataset.openSetup))})};
  document.getElementById('setupSearchBtn').onclick=draw;document.getElementById('setupSearch').addEventListener('keydown',e=>{if(e.key==='Enter')draw()});document.getElementById('manualSetupAdd').onclick=()=>renderSetupForm();document.getElementById('openSetupExcel').onclick=async()=>{try{await window.clinicAPI.openSetupWorkbook()}catch(e){showToast(errorMessage(e),'error')}};draw();
}

function copyField(label,value,key){return `<div class="copy-field"><div><span>${esc(label)}</span><strong>${esc(value||'—')}</strong></div>${value?`<button class="copy-btn" type="button" data-copy-setup="${esc(key)}">Copy</button>`:''}</div>`}
function emailDateText(v){
  if(!v)return '';
  const raw=String(v).trim();let y,m,d;
  let a=raw.match(/^(\d{4})-(\d{2})-(\d{2})/);if(a){y=+a[1];m=+a[2];d=+a[3]}else{a=raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!a)return raw;m=+a[1];d=+a[2];y=+a[3]}
  const dt=new Date(y,m-1,d);if(Number.isNaN(dt.getTime()))return raw;
  const suffix=(d%10===1&&d%100!==11)?'st':(d%10===2&&d%100!==12)?'nd':(d%10===3&&d%100!==13)?'rd':'th';
  return `${dt.toLocaleDateString('en-US',{weekday:'long'})}, ${dt.toLocaleDateString('en-US',{month:'long'})} ${d}${suffix}`;
}
function emailTimeText(v){const x=time12Value(v);if(!x)return '';return x.replace(/^0/,'').toLowerCase()}
function newPatientEmailText(template,r,virtual2Date='',virtual2Time=''){
  const name=String(r.patientName||'').trim();const examDate=emailDateText(r.examDate),examTime=emailTimeText(r.examTime),pcDate=emailDateText(r.parentMeetingDate),pcTime=emailTimeText(r.parentMeetingTime);const v2d=emailDateText(virtual2Date),v2t=emailTimeText(virtual2Time);
  const need=(label,val)=>{if(!val)throw new Error(`${label} is required for this email template.`);return val};
  if(template==='vde_child')return `Dear ${need('Patient Name',name)} family,\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nAppointment 1: The first portion of your child’s evaluation will be in our office on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime)}. We have blocked out two hours of time for your binocular vision evaluation. For the first hour, you will work with the vision specialist, followed by the doctor for the second hour.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached child questionnaire & an electronic secure contact form to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nAppointment 2: The second appointment is the consultation, which will be in our office with the doctor on ${need('Parent Meeting Date',pcDate)} at ${need('Parent Meeting Time',pcTime)}. This is time for you to have a discussion with the doctor, without your child present, as well as review the results and determine a treatment plan for your child.\n\nWe look forward to working with your family!`;
  if(template==='vde_adult')return `Dear ${need('Patient Name',name)},\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nAppointment 1: The first portion of your evaluation will be in our office on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime)}. We have blocked out two hours of time for your binocular vision evaluation. For the first hour, you will work with the vision specialist, followed by the doctor for the second hour.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached adult questionnaire & an electronic secure contact form to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nAppointment 2: The second appointment is the consultation, which will be in our office with the doctor on ${need('Parent Meeting Date',pcDate)} at ${need('Parent Meeting Time',pcTime)}. This is time for you to have a discussion with the doctor, as well as review the results and determine a treatment.\n\nWe look forward to working with you!`;
  if(template==='virtual_child')return `Dear ${need('Patient Name',name)} family,\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nIn order to reduce the amount of time spent in our office, the doctors are offering portions of your child's evaluation virtually. This also allows your child to be most comfortable during these portions of testing by not needing to wear a mask and be in their own home environment.\n\nAppointment 1: The first portion of your child's evaluation will be in our office on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime)}. We have blocked out an hour of time for the doctor to evaluate and work with your child.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached child questionnaire & an electronic secure contact form to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nAppointment 2: The second portion of your child's evaluation will be done virtually on ${need('Virtual Appointment 2 Date',v2d)} at ${need('Virtual Appointment 2 Time',v2t)} will be with the vision specialist and reviewed by the doctor.\n\nYou will receive an email from our vision specialist to connect to this appointment prior to your appointment time. If you have not received the link by the time of your appointment, please contact us.\n\nAppointment 3: The third appointment is the parent consultation, which will be done virtually with the doctor on ${need('Parent Meeting Date',pcDate)} at ${need('Parent Meeting Time',pcTime)}. This is time for you to have a discussion with the doctor, without your child present, as well as review the results and determine a treatment plan for your child.\n\nYou will receive an email from the doctor to connect to this appointment prior to your appointment time. If you have not received the link by the time of your appointment, please contact us.\n\nWe look forward to working with your family!`;
  if(template==='virtual_adult')return `Dear ${need('Patient Name',name)},\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nIn order to reduce the amount of time spent in our office, the doctors are offering portions of your evaluation virtually. This also allows you to be most comfortable during these portions of testing by not needing to wear a mask and be in your own home environment.\n\nAppointment 1: The first portion of your evaluation will be in our office on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime)}. We have blocked out an hour of time for the doctor to evaluate and work with you.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached adult questionnaire & a electronic secure contact form to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nAppointment 2: The second portion of your evaluation will be in our office on ${need('Virtual Appointment 2 Date',v2d)} at ${need('Virtual Appointment 2 Time',v2t)} will be with the vision specialist and reviewed by the doctor.\n\nYou will receive an email from the doctor to connect to this appointment prior to your appointment time. If you have not received the link by the time of your appointment, please contact us.\n\nAppointment 3: The third appointment is the patient consultation, which will be done virtually with the doctor on ${need('Parent Meeting Date',pcDate)} at ${need('Parent Meeting Time',pcTime)}. This is time for you to have a discussion with the doctor as well as review the results and determine a treatment plan.\n\nYou will receive an email from the doctor to connect to this appointment prior to your appointment time. If you have not received the link by the time of your appointment, please contact us.\n\nWe look forward to working with you!`;
  if(template==='vip_child')return `Dear ${need('Patient Name',name)} Family,\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nAppointment 1: The first portion of your child’s evaluation will be in our office on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime)}. We have blocked out two hours of time for your binocular vision evaluation. For the first hour, you will work with the vision specialist, followed by the doctor for the second hour.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached questionnaire & an electronic secure contact form to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nAppointment 2: The second appointment is the consultation, which will be in our office with the doctor on ${need('Parent Meeting Date',pcDate)} at ${need('Parent Meeting Time',pcTime)}. This is time for you to have a discussion with the doctor, as well as review the results and determine a treatment plan for your child (without your child present).\n\nWe look forward to working with your family!`;
  if(template==='vip_adult')return `Dear ${need('Patient Name',name)},\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nAppointment 1: The first portion of your evaluation will be in our office on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime)}. We have blocked out two hours of time for your binocular vision evaluation. For the first hour, you will work with the vision specialist, followed by the doctor for the second hour.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached questionnaire & an electronic secure contact form to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nAppointment 2: The second appointment is the consultation, which will be in our office with the doctor on ${need('Parent Meeting Date',pcDate)} at ${need('Parent Meeting Time',pcTime)}. This is time for you to have a discussion with the doctor, as well as review the results and determine a treatment plan for you.\n\nWe look forward to working with you!`;
  if(template==='99203_child')return `Dear ${need('Patient Name',name)} family,\n\nWe are so happy that we will be able to see you very soon for your upcoming appointment!\n\nYour child's in-office appointment will be on ${need('Exam Date',examDate)} at ${need('Exam Time',examTime).replace(' ','')}. We have blocked out one hour of time for your child's binocular vision evaluation.\n\nAttached you will find some information about how to find our office. Please let us know if you have any questions after you review it, as we are located on the second floor, which can sometimes be confusing when you arrive.\n\nYou will also find an attached child questionnaire to please fill out prior to your appointment. As we are trying to limit your time in our waiting room, please call us to let us know if you have any difficulty completing and returning this form.\n\nWe look forward to working with your family!`;
  throw new Error('Choose an email template.');
}
function emailRichHtml(template,text){
  const paras=String(text||'').split(/\n\n+/).filter(Boolean);
  const fmt=p=>{
    let h=esc(p);
    h=h.replace(/^(We are so happy[^\n]*)$/,'<strong>$1</strong>');
    h=h.replace(/^(Appointment [123]:[^]*?)(?= We have| This is| You will receive|$)/,'<strong>$1</strong>');
    h=h.replace(/^(Your child[^]*?)(?= We have|$)/,'<strong>$1</strong>');
    h=h.replace(/(how to find our office)/gi,'<u>$1</u>');
    h=h.replace(/(attached (?:child |adult )?questionnaire(?: &amp; an electronic secure contact form)?(?: to please fill out prior)?)/gi,'<u>$1</u>');
    h=h.replace(/^(We look forward[^\n]*)$/,'<strong>$1</strong>');
    return `<p style="margin:0 0 12pt 0;font-family:Calibri,Arial,sans-serif;font-size:11pt;line-height:1.15">${h}</p>`;
  };
  return `<div style="font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#000">${paras.map(fmt).join('')}</div>`;
}

function setupAppointmentPhrase(dateValue,timeValue){
  const d=emailDateText(dateValue),t=emailTimeText(timeValue).replace(/\s+(am|pm)$/i,'$1');
  if(!d||!t)return '';
  return `${d} at ${t}`;
}
function renderSetupEmailComposer(r){
  const host=document.getElementById('setupEmailHost');if(!host)return;
  const exam=setupAppointmentPhrase(r.examDate,r.examTime),parent=setupAppointmentPhrase(r.parentMeetingDate,r.parentMeetingTime);
  host.innerHTML=`<div class="email-composer"><div class="card-title-row"><h3>Appointment Date Phrases</h3><button type="button" class="icon-close" id="closeSetupEmail">×</button></div><p class="muted small">Copy the date/time phrase you need for the patient's email.</p><div class="copy-stack"><div class="copy-field"><div><span>Exam</span><strong>${esc(exam||'Date/time not available')}</strong></div>${exam?'<button class="copy-btn" type="button" id="copyExamPhrase">Copy</button>':''}</div><div class="copy-field"><div><span>Parent Meeting</span><strong>${esc(parent||'Date/time not available')}</strong></div>${parent?'<button class="copy-btn" type="button" id="copyParentPhrase">Copy</button>':''}</div></div>${exam&&parent?'<button type="button" class="btn" id="copyBothPhrases">Copy Both</button>':''}</div>`;
  document.getElementById('closeSetupEmail').onclick=()=>host.innerHTML='';
  const copy=async(text,label)=>{try{await window.clinicAPI.copyText(text);showToast(`${label} copied.`)}catch(e){showToast(errorMessage(e),'error')}};
  if(exam)document.getElementById('copyExamPhrase').onclick=()=>copy(exam,'Exam date');
  if(parent)document.getElementById('copyParentPhrase').onclick=()=>copy(parent,'Parent Meeting date');
  if(exam&&parent)document.getElementById('copyBothPhrases').onclick=()=>copy(`${exam}\n${parent}`,'Both date phrases');
}

async function renderSetupSidePanel(rowNumber){
  const panel=document.getElementById('setupSidePanel');if(!panel)return;panel.innerHTML='<div class="setup-empty-panel"><span>Loading…</span></div>';
  let r;try{r=await window.clinicAPI.getSetup(rowNumber)}catch(e){panel.innerHTML=`<div class="flash error">${esc(errorMessage(e))}</div>`;return}if(!r){panel.innerHTML='<div class="setup-empty-panel"><strong>Patient not found</strong></div>';return}
  const values={scheduledOn:fmtDate(r.scheduledOn),initialContactDate:fmtDate(r.initialContactDate),patientName:r.patientName,dob:fmtDate(r.dob),age:r.age,parentName:r.parentName,phone:r.phone,email:r.email,grade:r.grade,referralSource:r.referralSource,examType:r.examType,examDate:fmtDate(r.examDate),examTime:time12Value(r.examTime),parentMeetingDate:fmtDate(r.parentMeetingDate),parentMeetingTime:time12Value(r.parentMeetingTime)};
  panel.innerHTML=`<div class="setup-panel-head"><div><span class="eyebrow">New Patient Setup</span><h2>${esc(r.patientName)}</h2><span class="status ${r._state==='Completed'?'status-scheduled':'status-warning'}">${esc(r._state)}</span></div><button class="icon-close" id="closeSetupPanel" title="Close">×</button></div><div class="copy-stack">${copyField('Scheduled On',fmtDate(r.scheduledOn),'scheduledOn')}${copyField('Called',fmtDate(r.initialContactDate),'initialContactDate')}${copyField('Patient Name',r.patientName,'patientName')}${copyField('DOB',fmtDate(r.dob),'dob')}${copyField('Age',r.age,'age')}${copyField('Parent Name',r.parentName,'parentName')}${copyField('Phone',r.phone,'phone')}${copyField('Email',r.email,'email')}${copyField('Grade',r.grade,'grade')}${copyField('Referral Source',r.referralSource,'referralSource')}${copyField('Exam Type',r.examType,'examType')}${copyField('Exam Date',fmtDate(r.examDate),'examDate')}${copyField('Exam Time',time12Value(r.examTime),'examTime')}${copyField('Parent Meeting Date',fmtDate(r.parentMeetingDate),'parentMeetingDate')}${copyField('Parent Meeting Time',time12Value(r.parentMeetingTime),'parentMeetingTime')}</div><div class="setup-checklist"><h3>Setup Checklist</h3><label class="task-toggle"><input type="checkbox" id="setupAddCrystal" ${String(r.addPatientCrystal).toLowerCase()==='yes'?'checked':''}><span><strong>Add patient to Crystal</strong><small>Create the patient's Crystal profile.</small></span></label><label class="task-toggle"><input type="checkbox" id="setupScheduleCrystal" ${String(r.schedulePatientCrystal).toLowerCase()==='yes'?'checked':''}><span><strong>Schedule patient on Crystal</strong><small>Add the scheduled appointment(s).</small></span></label><label class="task-toggle"><input type="checkbox" id="setupEmail" ${String(r.sendInitialEmail).toLowerCase()==='yes'?'checked':''}><span><strong>Send initial email</strong><small>Send the initial patient email.</small></span></label><label>Notes<textarea id="setupNotes">${esc(r.notes||'')}</textarea></label><button class="btn btn-primary setup-save" id="saveSetupTasks">Save Progress</button><button class="btn setup-delete btn-danger" id="deleteSetupPatient">Delete Patient</button></div>`;
  document.getElementById('closeSetupPanel').onclick=()=>{panel.innerHTML='<div class="setup-empty-panel"><strong>Select a patient</strong><span>Patient information will appear here vertically for quick copy/paste into Crystal.</span></div>'};
  panel.querySelectorAll('[data-copy-setup]').forEach(btn=>btn.onclick=async()=>{const key=btn.dataset.copySetup;try{await window.clinicAPI.copyText(String(values[key]??''));showToast(`${btn.parentElement.querySelector('span').textContent} copied.`)}catch(e){showToast(errorMessage(e),'error')}});
  document.getElementById('saveSetupTasks').onclick=async()=>{try{await window.clinicAPI.updateSetup(rowNumber,{addPatientCrystal:document.getElementById('setupAddCrystal').checked?'YES':'',schedulePatientCrystal:document.getElementById('setupScheduleCrystal').checked?'YES':'',sendInitialEmail:document.getElementById('setupEmail').checked?'YES':'',notes:document.getElementById('setupNotes').value});showToast('New Patient Setup updated.');renderSetupLanding()}catch(e){showToast(errorMessage(e),'error')}};
  document.getElementById('deleteSetupPatient').onclick=async()=>{if(!confirm(`Delete ${r.patientName} from New Patient Setup? A backup will be created first.`))return;try{await window.clinicAPI.deleteSetup(rowNumber);showToast('Patient deleted from New Patient Setup.');renderSetupLanding()}catch(e){showToast(errorMessage(e),'error')}};
}

function renderSetupForm(rowNumber=null,r={}){
  const isEdit=!!rowNumber;setHeader('New Patient Setup');appEl.innerHTML=`<div class="form-shell"><div class="section-heading"><div><a class="back" id="backSetup">← Back to New Patient Setup</a><h1>${isEdit?'Edit Patient Setup':'Add Patient to New Patient Setup'}</h1><p class="muted">Use this only when a patient needs to be added manually.</p></div></div><form id="setupForm" class="form-card"><h2>Patient Information</h2><div class="grid three"><label>Initial Contact Date${dateTextInput('initialContactDate',r.initialContactDate||'')}</label><label>Scheduled On${dateTextInput('scheduledOn',r.scheduledOn||todayIso())}</label><label>Patient Name *<input name="patientName" required value="${esc(r.patientName||'')}"></label><label>Age<input type="number" min="0" max="130" name="age" value="${esc(r.age||'')}"></label><label>DOB${dateTextInput('dob',r.dob||'')}</label><label>Parent Name<input name="parentName" value="${esc(r.parentName||'')}"></label><label>Phone<input name="phone" value="${esc(r.phone||'')}"></label><label>Email<input name="email" value="${esc(r.email||'')}"></label><label>Grade<input name="grade" value="${esc(r.grade||'')}"></label><label>Referral Source<input name="referralSource" value="${esc(r.referralSource||'')}"></label></div><h2>Appointments</h2><div class="grid three"><label>Exam Type<input name="examType" value="${esc(r.examType||'')}"></label><label>Exam Date${dateTextInput('examDate',r.examDate||'')}</label><label>Exam Time${timeTextInput('examTime',r.examTime||'')}</label><label>Parent Meeting Date${dateTextInput('parentMeetingDate',r.parentMeetingDate||'')}</label><label>Parent Meeting Time${timeTextInput('parentMeetingTime',r.parentMeetingTime||'')}</label></div><h2>Setup Tracking</h2><div class="grid three"><label>Add Patient to Crystal<select name="addPatientCrystal"><option value=""></option><option value="YES" ${String(r.addPatientCrystal).toUpperCase()==='YES'?'selected':''}>YES</option></select></label><label>Schedule Patient on Crystal<select name="schedulePatientCrystal"><option value=""></option><option value="YES" ${String(r.schedulePatientCrystal).toUpperCase()==='YES'?'selected':''}>YES</option></select></label><label>Send Initial Email<select name="sendInitialEmail"><option value=""></option><option value="YES" ${String(r.sendInitialEmail).toUpperCase()==='YES'?'selected':''}>YES</option></select></label><label class="span-3">Notes<textarea name="notes">${esc(r.notes||'')}</textarea></label></div><div class="form-actions"><button type="button" class="btn" id="cancelSetupForm">Cancel</button><button type="submit" class="btn btn-primary">${isEdit?'Save Changes':'Add Patient'}</button></div></form></div>`;
  document.getElementById('backSetup').onclick=renderSetupLanding;document.getElementById('cancelSetupForm').onclick=renderSetupLanding;document.getElementById('setupForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());try{normalizeDates(data,[['scheduledOn','Scheduled On'],['initialContactDate','Initial Contact Date'],['dob','DOB'],['examDate','Exam Date'],['parentMeetingDate','Parent Meeting Date'],['waitlistDate','Waitlist Date']]);normalizeTimes(data,[['examTime','Exam Time'],['parentMeetingTime','Parent Meeting Time']])}catch(err){showToast(errorMessage(err),'error');return}try{if(isEdit)await window.clinicAPI.updateSetup(rowNumber,data);else await window.clinicAPI.addSetup(data);showToast(isEdit?'Patient setup updated.':'Patient added to New Patient Setup.');renderSetupLanding()}catch(err){showToast(errorMessage(err),'error')}};
}

