function closeSideNav(){const nav=document.getElementById('sideNav'),bd=document.getElementById('navBackdrop');if(!nav)return;nav.classList.remove('open');nav.setAttribute('aria-hidden','true');if(bd)bd.hidden=true;}
function wireGlobalNavigation(){
  const toggle=document.getElementById('menuToggle'),close=document.getElementById('menuClose'),bd=document.getElementById('navBackdrop');
  if(toggle)toggle.onclick=openSideNav;if(close)close.onclick=closeSideNav;if(bd)bd.onclick=closeSideNav;
  document.querySelectorAll('[data-nav]').forEach(btn=>btn.onclick=()=>{closeSideNav();const x=btn.dataset.nav;if(x==='home')renderDashboard();if(x==='referral')renderReferralHome();if(x==='setup')renderSetupLanding();if(x==='payment')renderInitialLanding();if(x==='cancellations')renderCancellationLanding();});
}

